// Written by scripts/app-css.mjs from apps/web's stylesheets: don't edit it by hand.
export const APP_CSS = "/* apps/web/src/shell/base.css */\n/*\n * Tokens (plan #style). The theme (T28: packages/ui/src/theme) sets every\n * colour, the fonts and the editor width on <html> (`--pm-bg`, `--pm-fg`,\n * `--pm-accent`…, see COLOUR_TOKENS) along with `data-mode` (light or dark).\n * Everything here is derived from those with color-mix, so each theme gets\n * the same hover, pressed, focus, soft and shadow states. Stylesheets never\n * write a colour literally (stylelint, A244).\n */\n:root {\n  color-scheme: light dark;\n  /* The note's status bar (A505): toasts float above it. */\n  --status-bar-height: 1.8rem;\n  --pm-hover: color-mix(in oklab, var(--pm-fg) 6%, transparent);\n  --pm-code-bg: color-mix(in oklab, var(--pm-bg), var(--pm-fg) 6%);\n  --pm-focus: color-mix(in oklab, var(--pm-accent) 70%, var(--pm-fg));\n  --pm-active: color-mix(in oklab, var(--pm-fg) 9%, transparent);\n  --pm-drop: color-mix(in oklab, var(--pm-accent) 14%, transparent);\n  --pm-radius: 0;\n  --pm-scrim: color-mix(in oklab, var(--pm-shadow-color) 28%, transparent);\n  --pm-shadow: 0 12px 40px color-mix(in oklab, var(--pm-shadow-color) 22%, transparent);\n  --pm-accent-soft: color-mix(in oklab, var(--pm-accent) 14%, transparent);\n  --pm-accent-line: color-mix(in oklab, var(--pm-accent) 45%, transparent);\n  /* Agent edits (T24): a colour of their own, apart from the accent and the user's selection. */\n  --pm-agent-soft: color-mix(in oklab, var(--pm-agent) 22%, transparent);\n  /* T36: the fidelity pass (A182). Derived colours, after the prototype's. */\n  --pm-border-strong: color-mix(in oklab, var(--pm-border), var(--pm-fg) 15%);\n  --pm-border-soft: color-mix(in oklab, var(--pm-border), var(--pm-bg) 45%);\n  --pm-danger-soft: color-mix(in oklab, var(--pm-danger) 12%, transparent);\n  --pm-accent-softer: color-mix(in oklab, var(--pm-accent) 8%, transparent);\n  --pm-ring: 0 0 0 3px color-mix(in oklab, var(--pm-accent) 18%, transparent);\n  --pm-shadow-1: 0 1px 2px color-mix(in oklab, var(--pm-shadow-color) 8%, transparent);\n  /* Shape. */\n  --pm-radius-sm: 0;\n  --pm-radius-lg: 0;\n  --pm-radius-xl: 0;\n  --pm-radius-sheet: 0;\n  /* Controls: buttons and fields, and the touch size on phones (44 px, A183). */\n  --pm-control: 2rem;\n  --pm-control-sm: 1.75rem;\n  --pm-hit: 2.75rem;\n  --pm-bar: 3.5rem;\n  --pm-ease: cubic-bezier(0.2, 0.7, 0.2, 1);\n  --pm-fast: 120ms;\n  --pm-medium: 200ms;\n}\n\n/* Shadows read heavier on dark surfaces. */\n:root[data-mode='dark'] {\n  --pm-shadow-1: 0 1px 2px color-mix(in oklab, var(--pm-shadow-color) 30%, transparent);\n}\n\nbody {\n  margin: 0;\n  background: var(--pm-bg);\n  color: var(--pm-fg);\n  font-family: var(--pm-font);\n  /* Text that names no role of its own is running text (type.css, A1561). */\n  font-size: var(--pm-text-body);\n  -webkit-font-smoothing: antialiased;\n  -webkit-tap-highlight-color: transparent;\n}\n\na {\n  color: var(--pm-link, var(--pm-accent));\n}\n\n.app-shell {\n  max-width: 40rem;\n  margin: 0 auto;\n  padding: max(3rem, env(safe-area-inset-top)) 1rem 3rem;\n}\n\n.app-shell h1 {\n  margin: 0 0 0.5rem;\n  font-size: var(--pm-text-page-title);\n  letter-spacing: -0.01em;\n}\n\n.app-shell p {\n  color: var(--pm-muted);\n  margin: 0;\n}\n\n/* A section's sub-headings, one step below its title in every section (T39 pass 2). */\n.settings h3,\n.settings-section h3 {\n  margin: 2rem 0 0.5rem;\n  font-size: var(--pm-text-group-head);\n  font-weight: var(--pm-weight-group-head);\n}\n\n/*\n * Devices' too, past its empty status line: its first sub-heading sat 32px under the title,\n * Status's 20px (A988).\n */\n.settings h2 + h3,\n.settings h2 + p:empty + h3,\n.settings-section h2 + h3 {\n  margin-top: 1.25rem;\n}\n\n.settings p {\n  margin: 0.25rem 0 0.75rem;\n}\n\n.list {\n  margin: 0 0 1rem;\n  padding: 0;\n  overflow: hidden;\n  border: 1px solid var(--pm-border);\n  border-radius: 0;\n  background: var(--pm-raised);\n  list-style: none;\n}\n\n.list:empty {\n  display: none;\n}\n\n.list li {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  min-height: 3.25rem;\n  padding: 0.5rem 0.75rem;\n  border-bottom: 1px solid var(--pm-border-soft);\n  font-size: var(--pm-text-item);\n}\n\n.list li:last-child {\n  border-bottom: 0;\n}\n\n.list small {\n  color: var(--pm-muted);\n}\n\n.row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n  align-items: center;\n}\n\n.secret {\n  margin: 1rem 0;\n  padding: 0.85rem 1rem;\n  border: 1px solid var(--pm-accent-line);\n  border-radius: 0;\n  background: var(--pm-accent-softer);\n}\n\n.secret code {\n  display: block;\n  margin: 0.5rem 0 0.75rem;\n  padding: 0.5rem 0.65rem;\n  border: 1px solid var(--pm-border);\n  border-radius: 0;\n  background: var(--pm-raised);\n  font-family: var(--pm-mono);\n  font-size: var(--pm-text-code);\n  overflow-wrap: anywhere;\n}\n\n.error {\n  color: var(--pm-danger);\n}\n\n/* apps/web/src/shell/sr-only.css */\n/*\n * Read only by a screen reader, never shown: the one rule, for the app (styles.css), the graph\n * (graph.css, which Android's graph page loads too) and the editor's symbols label.\n */\n.sr-only,\n.pm-symbols-label {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n/* apps/web/src/shell/type.css */\n/*\n * Type (A1561): one scale, and the roles every screen's text takes from it. A stylesheet never\n * writes a font size, weight or line height itself (stylelint, scripts/stylelint-type.mjs): it\n * names the role its text plays (`--pm-text-help`, or the `t-help` class), or for a one-off\n * (a glyph, a miniature) a step of the scale. So a note under a setting is the same size as\n * every other note under a setting, and a child is never larger than its parent's heading.\n *\n * The note's own text (its title, headings, code, the margin's symbols) has a scale of its own\n * at the end, relative to the Note Font Size (A944); it is the note's typography, not chrome.\n */\n:root {\n  /* The scale: the prototype's 11.5, 13, 14 and 16 px (A182), and a step or two either side. */\n  --pm-text-2xs: 0.65rem; /* 10.4 px */\n  --pm-text-xs: 0.72rem; /* 11.5 px */\n  --pm-text-sm: 0.8125rem; /* 13 px */\n  --pm-text-md: 0.875rem; /* 14 px */\n  --pm-text-lg: 1rem; /* 16 px */\n  --pm-text-xl: 1.125rem; /* 18 px */\n  --pm-text-2xl: 1.25rem; /* 20 px */\n  --pm-text-3xl: 1.5rem; /* 24 px */\n  --pm-text-4xl: 1.75rem; /* 28 px */\n  --pm-text-5xl: 2rem; /* 32 px */\n  --pm-weight-regular: 400;\n  --pm-weight-medium: 500;\n  --pm-weight-semibold: 600;\n  --pm-weight-bold: 700;\n  --pm-leading-none: 1;\n  --pm-leading-tight: 1.25;\n  --pm-leading-snug: 1.4;\n  --pm-leading-relaxed: 1.5;\n\n  /*\n   * The roles, largest first. Each has a size, a weight and a line height (`normal` where the\n   * text sits in a row whose height is set elsewhere), and a colour where the role has one.\n   */\n  /* A page's title: Settings, Trash, Tags, the welcome. */\n  --pm-text-page-title: var(--pm-text-5xl);\n  --pm-weight-page-title: var(--pm-weight-bold);\n  --pm-leading-page-title: var(--pm-leading-tight);\n  /* The page's title again, small, in a bar pinned over the page once it scrolls. */\n  --pm-text-bar-title: var(--pm-text-xl);\n  --pm-weight-bar-title: var(--pm-weight-bold);\n  --pm-leading-bar-title: var(--pm-leading-tight);\n  /* A section of a page: a Settings page's own title (Appearance, Sidebar…). */\n  --pm-text-section-head: var(--pm-text-xl);\n  --pm-weight-section-head: var(--pm-weight-bold);\n  --pm-leading-section-head: var(--pm-leading-tight);\n  /* A group within a section (Shortcuts, Sections), a card's title. */\n  --pm-text-group-head: var(--pm-text-lg);\n  --pm-weight-group-head: var(--pm-weight-semibold);\n  --pm-leading-group-head: var(--pm-leading-tight);\n  /* A dialog's or a sheet's title. */\n  --pm-text-dialog-title: var(--pm-text-lg);\n  --pm-weight-dialog-title: var(--pm-weight-semibold);\n  --pm-leading-dialog-title: var(--pm-leading-tight);\n  /* Running text: a page's or a dialog's paragraphs. */\n  --pm-text-body: var(--pm-text-md);\n  --pm-weight-body: var(--pm-weight-regular);\n  --pm-leading-body: var(--pm-leading-relaxed);\n  /* A setting's or a field's name. */\n  --pm-text-row-label: var(--pm-text-sm);\n  --pm-weight-row-label: var(--pm-weight-semibold);\n  --pm-leading-row-label: normal;\n  /* A thing you pick or press: a menu item, a button, a list or table row, a tab, a toast. */\n  --pm-text-item: var(--pm-text-sm);\n  --pm-weight-item: var(--pm-weight-regular);\n  --pm-leading-item: normal;\n  /* A row of the sidebar: its notes, folders, tags and shortcuts. */\n  --pm-text-sidebar-item: var(--pm-text-sm);\n  /* What you type into: fields and selects. */\n  --pm-text-field: var(--pm-text-sm);\n  /* What a row, a group or a panel means: a setting's help, a note under a form, a hint. */\n  --pm-text-help: var(--pm-text-xs);\n  --pm-weight-help: var(--pm-weight-regular);\n  --pm-leading-help: var(--pm-leading-snug);\n  --pm-color-help: var(--pm-muted);\n  /* About a thing, beside or under it: a time, a count, a path, a status, a caption. */\n  --pm-text-meta: var(--pm-text-xs);\n  --pm-weight-meta: var(--pm-weight-regular);\n  --pm-leading-meta: normal;\n  --pm-color-meta: var(--pm-muted);\n  /* A list's heading over its items: a sidebar section, a menu's group, a panel's heading. */\n  --pm-text-list-head: var(--pm-text-xs);\n  --pm-weight-list-head: var(--pm-weight-semibold);\n  --pm-leading-list-head: normal;\n  --pm-color-list-head: var(--pm-muted);\n  /* A chip, a key cap, a scope marker. */\n  --pm-text-badge: var(--pm-text-xs);\n  --pm-weight-badge: var(--pm-weight-semibold);\n  --pm-leading-badge: normal;\n  /* A count on a tab or an icon, and the text of a miniature. */\n  --pm-text-micro: var(--pm-text-2xs);\n  --pm-weight-micro: var(--pm-weight-semibold);\n  /* A tooltip. */\n  --pm-text-tooltip: var(--pm-text-xs);\n  --pm-weight-tooltip: var(--pm-weight-medium);\n  --pm-leading-tooltip: var(--pm-leading-snug);\n  /* Code and other monospaced text in the chrome: a diff, a source, a command. */\n  --pm-text-code: var(--pm-text-sm);\n  --pm-leading-code: var(--pm-leading-relaxed);\n  /* Code inside a line of chrome text. */\n  --pm-text-code-inline: 0.85em;\n  /* A code to read out or type somewhere else (GitHub's device code). */\n  --pm-text-display: var(--pm-text-4xl);\n  --pm-weight-display: var(--pm-weight-semibold);\n  /* A notebook badge's letter, as a share of its square (badge.css). */\n  --pm-badge-glyph-ratio: 0.62;\n\n  /*\n   * The note's own scale, from the Note Font Size (A944): the title a step above a first\n   * heading (A554), headings in em of the text, code a little smaller than it.\n   */\n  --pm-note-text-size: var(--pm-note-size, 16px);\n  --pm-note-leading: 1.7;\n  --pm-note-title-size: calc(var(--pm-note-size, 16px) * 1.9);\n  --pm-note-title-weight: var(--pm-weight-bold);\n  --pm-note-title-leading: 1.2;\n  --pm-note-h1-size: 1.6em;\n  --pm-note-h2-size: 1.28em;\n  --pm-note-h3-size: 1.07em;\n  --pm-note-heading-leading: 1.3;\n  --pm-note-code-size: 0.86em;\n  --pm-note-code-leading: 1.55;\n  /* A callout's type and title, in the interface font. */\n  --pm-note-callout-type-size: 0.92rem;\n  --pm-note-callout-title-size: 0.95rem;\n  /*\n   * The gutter's symbols (A1680): one size on every line, a little under the note's text, so\n   * the gutter's three slots hold a heading's too; their line height is the line's own, so they\n   * sit level with its text. Their \"+N\" in em of them.\n   */\n  --pm-note-symbol-size: calc(var(--pm-note-size, 16px) * 0.9);\n  --pm-note-symbol-leading: 1lh;\n  --pm-note-symbol-more-size: 0.7em;\n  --pm-note-symbol-badge-size: 0.6em;\n  /* A gutter slot in em of the note's text: a glyph's 1.1em and its gap, an emoji's width. */\n  --pm-note-symbol-slot: 1.125em;\n  /* The widget's padding and the gap it keeps from the text. */\n  --pm-note-symbol-gutter-gap: calc(0.2em + 0.3rem);\n  /* An agent's name on its edit. */\n  --pm-note-agent-label-size: 0.7em;\n  /* Appearance's preview of a note, a little under the note's own sizes. */\n  --pm-note-preview-title-size: calc(var(--pm-note-size, 16px) * 1.15);\n  --pm-note-preview-text-size: calc(var(--pm-note-size, 16px) * 0.875);\n  --pm-note-preview-code-size: calc(var(--pm-note-size, 16px) * 0.85);\n}\n\n/* Phones: titles a step smaller, and the note's title a little under the desktop's (A554). */\n@media (max-width: 700px) {\n  :root {\n    --pm-text-page-title: var(--pm-text-3xl);\n    --pm-note-title-size: calc(var(--pm-note-size, 16px) * 1.85);\n  }\n}\n\n/* Touch: the sidebar's rows a step larger, and fields at 16 px so iOS never zooms into them. */\n@media (max-width: 700px), (pointer: coarse) {\n  :root {\n    --pm-text-sidebar-item: var(--pm-text-md);\n    --pm-text-field: var(--pm-text-lg);\n  }\n}\n\n/*\n * The roles as classes, for an element whose stylesheet has nothing else to say about it\n * (`<p className=\"t-help\">`). Each sets the role's size, weight, line height and colour.\n */\n.t-page-title {\n  font-size: var(--pm-text-page-title);\n  font-weight: var(--pm-weight-page-title);\n  line-height: var(--pm-leading-page-title);\n}\n\n.t-bar-title {\n  font-size: var(--pm-text-bar-title);\n  font-weight: var(--pm-weight-bar-title);\n  line-height: var(--pm-leading-bar-title);\n}\n\n.t-section-head {\n  font-size: var(--pm-text-section-head);\n  font-weight: var(--pm-weight-section-head);\n  line-height: var(--pm-leading-section-head);\n}\n\n.t-group-head {\n  font-size: var(--pm-text-group-head);\n  font-weight: var(--pm-weight-group-head);\n  line-height: var(--pm-leading-group-head);\n}\n\n.t-dialog-title {\n  font-size: var(--pm-text-dialog-title);\n  font-weight: var(--pm-weight-dialog-title);\n  line-height: var(--pm-leading-dialog-title);\n}\n\n.t-body {\n  font-size: var(--pm-text-body);\n  font-weight: var(--pm-weight-body);\n  line-height: var(--pm-leading-body);\n}\n\n.t-row-label {\n  font-size: var(--pm-text-row-label);\n  font-weight: var(--pm-weight-row-label);\n  line-height: var(--pm-leading-row-label);\n}\n\n.t-item {\n  font-size: var(--pm-text-item);\n  font-weight: var(--pm-weight-item);\n  line-height: var(--pm-leading-item);\n}\n\n.t-help {\n  color: var(--pm-color-help);\n  font-size: var(--pm-text-help);\n  font-weight: var(--pm-weight-help);\n  line-height: var(--pm-leading-help);\n}\n\n.t-meta {\n  color: var(--pm-color-meta);\n  font-size: var(--pm-text-meta);\n  font-weight: var(--pm-weight-meta);\n  line-height: var(--pm-leading-meta);\n}\n\n.t-list-head {\n  color: var(--pm-color-list-head);\n  font-size: var(--pm-text-list-head);\n  font-weight: var(--pm-weight-list-head);\n  line-height: var(--pm-leading-list-head);\n}\n\n.t-badge {\n  font-size: var(--pm-text-badge);\n  font-weight: var(--pm-weight-badge);\n  line-height: var(--pm-leading-badge);\n}\n\n.t-code {\n  font-family: var(--pm-mono);\n  font-size: var(--pm-text-code);\n  line-height: var(--pm-leading-code);\n}\n\n/* apps/web/src/shell/shell.css */\n/* Notes shell (T6): sidebar with the note list, and the open note. Loosely after prototype/. */\n.notes-app {\n  display: grid;\n  /* The sidebar's width, dragged by its edge (A1122): set on the element, 17rem until then. */\n  grid-template-columns: var(--pm-sidebar-width, 17rem) minmax(0, 1fr);\n  height: 100vh;\n  height: 100dvh;\n}\n\n/*\n * The page is a column the window's height (the T39 review, T41): whatever sits above the\n * notes (the \"Sign in again\" banner) takes its own height and the notes take the rest, so the\n * page never scrolls as a whole. Other screens (Settings pages, sign-in approval) keep their\n * own height and the page scrolls past it as before.\n */\n#root {\n  display: flex;\n  flex-direction: column;\n  height: 100vh;\n  height: 100dvh;\n}\n\n#root > .notes-app {\n  flex: 1 1 0;\n  min-height: 0;\n  height: auto;\n}\n\n#root > .app-shell,\n#root > .settings-shell {\n  box-sizing: border-box;\n  width: 100%;\n}\n\n/*\n * A window with none of the app in it yet (the wait for the notebooks, the first run; FirstRun.tsx):\n * what it shows scrolls in `.window-bare`, under `.window-drag`, a strip across the window's top\n * that drags it with the compact title bar (Ryan's review of #192, finding 1). Without that title\n * bar the strip takes no room.\n */\n#root > .window-drag {\n  display: none;\n}\n\n:root[data-titlebar='compact'] #root > .window-drag {\n  display: block;\n  flex: none;\n  height: var(--pm-titlebar-row);\n}\n\n#root > .window-bare {\n  flex: 1 1 0;\n  min-height: 0;\n  overflow-y: auto;\n}\n\n.window-bare > .app-shell {\n  box-sizing: border-box;\n}\n\n.sidebar {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  background: var(--pm-sidebar);\n  border-right: 1px solid var(--pm-border);\n}\n\n.sb-head {\n  display: flex;\n  align-items: center;\n  gap: 0.25rem;\n  padding: 0.75rem 0.5rem 0.4rem 0.875rem;\n}\n\n.brand {\n  display: flex;\n  flex: 1;\n  align-items: center;\n  gap: 0.5rem;\n  min-width: 0;\n  margin: 0;\n  color: var(--pm-fg);\n  font-size: var(--pm-text-md);\n  font-weight: var(--pm-weight-semibold);\n  letter-spacing: -0.01em;\n}\n\n/* The logo (A402): its light tile, or its dark one in dark mode (data-mode, else the system's). */\n.brand-mark {\n  display: flex;\n  flex: none;\n}\n\n.brand-mark > img {\n  display: block;\n}\n\n.brand-mark > .brand-mark-dark,\n:root[data-mode='dark'] .brand-mark > .brand-mark-light {\n  display: none;\n}\n\n:root[data-mode='dark'] .brand-mark > .brand-mark-dark {\n  display: block;\n}\n\n@media (prefers-color-scheme: dark) {\n  :root:not([data-mode]) .brand-mark > .brand-mark-light {\n    display: none;\n  }\n\n  :root:not([data-mode]) .brand-mark > .brand-mark-dark {\n    display: block;\n  }\n}\n\n/* Only in the phone's drawer (below); the specificity outranks .icon-btn's display. */\n.sb-head .drawer-close {\n  display: none;\n}\n\n.sb-actions {\n  display: grid;\n  gap: 1px;\n  padding: 0.25rem 0.5rem 0.5rem;\n}\n\n/*\n * New Note, then Search, Today, This Week, Graph, Notebooks and Commands, and ⋯ at the end: one\n * row of icons (T51, A932; T52; T53). The icons give up a little width rather than wrap: with\n * no `min-width` the row, a grid item, kept its icons' full widths and ran past the sidebar's\n * edge, cutting ⋯ off (T53 pass).\n */\n.sb-shortcuts {\n  display: flex;\n  min-width: 0;\n  gap: 2px;\n}\n\n.sb-shortcuts .sb-shortcut:not(.new-note) {\n  flex: 0 1 var(--pm-control);\n  min-width: 1.5rem;\n}\n\n/* New Note leads the row in the accent's fill, as the primary button did (T52). */\n.sb-shortcut.new-note {\n  margin-inline-end: 0.3rem;\n  background: var(--pm-accent);\n  color: var(--pm-on-accent);\n}\n\n.sb-shortcut.new-note:hover:not(:disabled) {\n  background: color-mix(in oklab, var(--pm-accent), var(--pm-fg) 12%);\n  color: var(--pm-on-accent);\n}\n\n.sb-shortcut.new-note:active:not(:disabled) {\n  background: color-mix(in oklab, var(--pm-accent), var(--pm-fg) 20%);\n  color: var(--pm-on-accent);\n}\n\n.sb-shortcut[aria-current='page'],\n.sb-foot .icon-btn[aria-current='page'] {\n  background: var(--pm-active);\n  color: var(--pm-fg);\n}\n\n/* Back and Forward at the start of the sidebar's head, the window's first row (T51, A943). */\n.history-nav {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 2px;\n}\n\n/*\n * Back and Forward as one compact pair (T52): two half-width buttons on one quiet chip, a hairline\n * between them, each still 28 px tall with its own hover, focus ring and disabled state.\n */\n.history-pair {\n  display: inline-flex;\n  flex: none;\n  height: var(--pm-control-sm);\n  border-radius: 0;\n  background: color-mix(in oklab, var(--pm-fg) 5%, transparent);\n}\n\n.history-pair .history-half {\n  position: relative;\n  width: 1.375rem;\n  height: 100%;\n  border-radius: 0;\n}\n\n.history-pair .history-half:first-child {\n  border-radius: 0;\n}\n\n.history-pair .history-half:last-child {\n  border-radius: 0;\n}\n\n.history-pair .history-half + .history-half::before {\n  position: absolute;\n  top: 25%;\n  bottom: 25%;\n  left: 0;\n  width: 1px;\n  background: var(--pm-border);\n  content: '';\n}\n\n/* The ring above the other half. */\n.history-pair .history-half:focus-visible {\n  z-index: 1;\n}\n\n@media (max-width: 700px), (pointer: coarse) {\n  .history-pair {\n    height: var(--pm-hit);\n  }\n\n  .history-pair .history-half {\n    width: 2.25rem;\n    height: 100%;\n  }\n}\n\n/*\n * Buttons (T36): one height, radius and set of states, light and dark. Border-box, so a link\n * drawn as a button is the height of a real one, not 2px taller (A988).\n */\n.btn {\n  display: inline-flex;\n  flex: none;\n  box-sizing: border-box;\n  align-items: center;\n  justify-content: center;\n  gap: 0.4rem;\n  height: var(--pm-control);\n  padding: 0 0.75rem;\n  border: 1px solid var(--pm-border);\n  border-radius: 0;\n  background: var(--pm-raised);\n  box-shadow: var(--pm-shadow-1);\n  color: var(--pm-fg);\n  font: inherit;\n  font-size: var(--pm-text-item);\n  font-weight: var(--pm-weight-medium);\n  white-space: nowrap;\n  text-decoration: none;\n  cursor: pointer;\n  transition:\n    background var(--pm-fast),\n    border-color var(--pm-fast),\n    color var(--pm-fast);\n}\n\n.btn:hover {\n  border-color: var(--pm-border-strong);\n}\n\n.btn:active {\n  background: color-mix(in oklab, var(--pm-raised), var(--pm-fg) 6%);\n}\n\n.btn:disabled,\n.icon-btn:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n\n.btn.primary {\n  border-color: var(--pm-accent);\n  background: var(--pm-accent);\n  color: var(--pm-on-accent);\n}\n\n.btn.primary:hover:not(:disabled) {\n  background: color-mix(in oklab, var(--pm-accent), var(--pm-fg) 12%);\n}\n\n.btn.danger {\n  color: var(--pm-danger);\n}\n\n.btn.danger:hover:not(:disabled) {\n  border-color: color-mix(in oklab, var(--pm-danger) 45%, transparent);\n  background: var(--pm-danger-soft);\n}\n\n/* Solid red: an action that deletes (Delete Model…, a confirm's Delete; A1595). */\n.btn.danger-fill {\n  border-color: var(--pm-danger);\n  background: var(--pm-danger);\n  color: var(--pm-on-accent);\n}\n\n.btn.danger-fill:hover:not(:disabled) {\n  border-color: color-mix(in oklab, var(--pm-danger), var(--pm-fg) 12%);\n  background: color-mix(in oklab, var(--pm-danger), var(--pm-fg) 12%);\n}\n\n.btn kbd {\n  font-family: var(--pm-font);\n  font-size: var(--pm-text-badge);\n  font-weight: var(--pm-weight-medium);\n  line-height: var(--pm-leading-none);\n  opacity: 0.8;\n}\n\n/* On the accent, a key is outlined in the button's own text colour (4.5:1, not faded). */\n.btn.primary .keys kbd {\n  border-color: color-mix(in oklab, var(--pm-on-accent) 45%, transparent);\n  background: transparent;\n  color: var(--pm-on-accent);\n  opacity: 1;\n}\n\n.btn .i,\n.icon-btn .i,\n.sb-item .i,\n.menu-item .i {\n  flex: none;\n}\n\n:focus-visible {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: 1px;\n}\n\n/* Sidebar rows (T36, after the prototype): an icon, a label, and keys on hover or focus. */\n.sb-item {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  width: 100%;\n  min-height: var(--pm-control-sm);\n  padding: 0 0.5rem;\n  border: 0;\n  border-radius: 0;\n  background: none;\n  color: var(--pm-muted);\n  font: inherit;\n  font-size: var(--pm-text-sidebar-item);\n  text-align: left;\n  text-decoration: none;\n  white-space: nowrap;\n  cursor: pointer;\n}\n\n.sb-item:hover {\n  background: var(--pm-hover);\n  color: var(--pm-fg);\n}\n\n.sb-item:focus-visible {\n  outline-offset: -2px;\n}\n\n.sb-item[aria-current='page'] {\n  background: var(--pm-active);\n  color: var(--pm-fg);\n  font-weight: var(--pm-weight-medium);\n}\n\n.sb-item .label {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.sb-list {\n  display: flex;\n  flex: 1;\n  flex-direction: column;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 0;\n}\n\n.list-empty {\n  margin: 0.5rem;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n}\n\n.note-list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* apps/web/src/shell/controls.css */\n/*\n * The note's header (T36): the note's folders, then its actions, after the prototype's editor bar.\n * Its end padding is the tab strip's (links.css), so the last action sits over the strip's icons,\n * on one column (A988). In the sidebar's colour, so the title bar reads apart from the text in\n * every theme, light and dark (PEN-135 item 7).\n */\n.note-top {\n  position: sticky;\n  top: 0;\n  z-index: 2;\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  height: 3rem;\n  padding: 0 0.3rem 0 1rem;\n  border-bottom: 1px solid var(--pm-border-soft);\n  background: var(--pm-sidebar);\n}\n\n/*\n * Beside the rail, Back, Forward and the pin start the note's title bar (PEN-135 item 6), flush\n * and as tall as the row, as in the sidebar's head (A1135): from the rail's edge, or after the\n * traffic lights' room in the Mac app, a hairline either side.\n */\n.note-top:has(> .note-top-lead) {\n  padding-left: 0;\n}\n\n.note-top-lead {\n  display: flex;\n  flex: none;\n  align-self: stretch;\n  border-right: 1px solid var(--pm-border-soft);\n}\n\n.note-top-lead .history-nav {\n  align-self: stretch;\n}\n\n.note-top-lead .history-pair {\n  height: 100%;\n  background: none;\n}\n\n.note-top-lead .history-pair .history-half {\n  width: 2rem;\n}\n\n.note-top-lead .history-half + .history-half::before {\n  top: 0;\n  bottom: 0;\n  background: var(--pm-border-soft);\n}\n\n.note-top-lead > .icon-btn {\n  width: 2.5rem;\n  height: 100%;\n  border-left: 1px solid var(--pm-border-soft);\n}\n\n.note-top-lead + .crumbs {\n  margin-left: 0.5rem;\n}\n\n.crumbs {\n  flex: 1;\n  min-width: 0;\n}\n\n.crumbs ol {\n  display: flex;\n  align-items: center;\n  margin: 0;\n  padding: 0;\n  overflow: hidden;\n  list-style: none;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-item);\n  white-space: nowrap;\n}\n\n.crumbs li {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  gap: 0.3rem;\n  margin-right: 0.3rem;\n}\n\n.crumbs li .i {\n  opacity: 0.6;\n}\n\n.crumbs li.crumb-notebook .i:first-child {\n  opacity: 1;\n  color: var(--pm-accent);\n}\n\n.crumbs li[aria-current='page'] {\n  flex: 0 1 auto;\n  min-width: 0;\n  display: block;\n  overflow: hidden;\n  color: var(--pm-fg);\n  text-overflow: ellipsis;\n}\n\n.note-actions {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 2px;\n}\n\n.note-top .sep {\n  width: 1px;\n  height: 1.1rem;\n  margin: 0 0.3rem;\n  background: var(--pm-border-strong);\n}\n\n/* Pressed is the accent's tint, so an open panel or the source view reads at a glance. */\n.note-actions .icon-btn[aria-pressed='true'] {\n  background: var(--pm-accent-soft);\n  color: var(--pm-accent);\n}\n\n.btn.quiet {\n  height: var(--pm-control-sm);\n  padding: 0 0.6rem;\n  border-color: transparent;\n  background: transparent;\n  box-shadow: none;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-item);\n}\n\n.btn.quiet:hover:not(:disabled) {\n  background: var(--pm-hover);\n  color: var(--pm-fg);\n}\n\n/* A quiet destructive action (Delete for good) is red too, without a fill. */\n.btn.quiet.danger,\n.btn.quiet.danger:hover:not(:disabled) {\n  color: var(--pm-danger);\n}\n\n/*\n * Beside a full button (Cancel by Save, Delete for Good by Restore) a quiet one is as tall, so\n * its hover box is not 4px shorter than its neighbour; as are a symbol's icon buttons, in a row\n * of full-height controls (A988). A minimum, so touch keeps its 44px.\n */\n:is(.capture, .feedback-dlg, .trash, .settings-content)\n  .btn.quiet:is(.btn:not(.quiet) ~ *, :has(~ .btn:not(.quiet))),\n.symbol-actions .btn.quiet {\n  min-height: var(--pm-control);\n}\n\n/* The note header's Copy menu (T15). */\n.menu-anchor {\n  position: relative;\n}\n\n.menu {\n  position: absolute;\n  top: calc(100% + 0.25rem);\n  right: 0;\n  z-index: 40;\n  display: flex;\n  flex-direction: column;\n  min-width: 14rem;\n  padding: 0.25rem;\n  border: 1px solid var(--pm-border);\n  border-radius: 0;\n  background: var(--pm-raised);\n  box-shadow: var(--pm-popover-shadow);\n  animation: pm-rise var(--pm-medium) var(--pm-ease);\n}\n\n.menu-item {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  min-height: var(--pm-control);\n  padding: 0 0.6rem;\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  color: var(--pm-fg);\n  font: inherit;\n  font-size: var(--pm-text-item);\n  text-align: left;\n  white-space: nowrap;\n  cursor: pointer;\n}\n\n.menu-item .i {\n  color: var(--pm-muted);\n}\n\n.menu-item:hover,\n.menu-item:focus {\n  outline: none;\n  background: var(--pm-hover);\n}\n\n.menu-item:focus-visible {\n  box-shadow: inset 0 0 0 2px var(--pm-focus);\n}\n\n.menu-item.danger,\n.menu-item.danger .i {\n  color: var(--pm-danger);\n}\n\n/* The tree's context menu (A570): fixed at the pointer, not under a button. */\n.menu.context-menu {\n  position: fixed;\n  right: auto;\n  z-index: 60;\n}\n\n/* The notes a context menu acts on (review S1): named above its items. */\n.menu-caption {\n  max-width: 18rem;\n  margin: 0;\n  padding: 0.3rem 0.6rem 0.4rem;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-meta);\n  overflow-wrap: anywhere;\n}\n\n/* Selected notes in the tree (A570), and folders picked with them (T68, #230). */\n.tree-row.note-row[aria-selected='true'],\n.tree-row.folder-row[data-picked] {\n  background: var(--pm-accent-soft);\n}\n\n/* The note's actions menu (A575): label, then the command's keys, then On for a toggle. */\n.menu-item .menu-label {\n  flex: 1;\n}\n\n.menu-keys {\n  display: inline-flex;\n  margin-left: 1rem;\n  color: var(--pm-muted);\n}\n\n.menu[data-sheet] .menu-keys {\n  display: none;\n}\n\n.menu-item[aria-checked='true']::after {\n  margin-left: auto;\n  padding-left: 1rem;\n  color: var(--pm-accent);\n  content: 'On';\n  font-size: var(--pm-text-badge);\n  font-weight: var(--pm-weight-badge);\n}\n\n/*\n * A menu with toggles keeps a column for On at the end of every item, empty when off, so the\n * keys line up whether an item is on or not; On used to push its row's keys left (A988).\n */\n.menu:has(> .menu-item[role='menuitemcheckbox']) > .menu-item::after {\n  flex: none;\n  box-sizing: border-box;\n  width: 2.25rem;\n  margin-left: 0;\n  padding-left: 1rem;\n  text-align: right;\n}\n\n.menu:has(> .menu-item[role='menuitemcheckbox']) > .menu-item:not([aria-checked='true'])::after {\n  content: '';\n}\n\n/* A choice (the sort order, T52): a check before the one in use, not On after it. */\n.menu-item[role='menuitemradio'][aria-checked='true']::after {\n  content: none;\n}\n\n.menu-check {\n  display: inline-grid;\n  flex: none;\n  place-items: center;\n  width: 1rem;\n}\n\n.menu-check .i {\n  color: var(--pm-accent);\n}\n\n.menu-sep {\n  height: 1px;\n  margin: 0.3rem 0.5rem;\n  background: var(--pm-border);\n}\n\n.menu-scrim {\n  display: none;\n}\n\n/*\n * The window's toasts (PEN-63): one stack at the bottom centre, newest at the bottom, 8 px\n * apart, at most three. It never takes the pointer; only a toast with controls does (A558).\n */\n.toast-stack {\n  position: fixed;\n  z-index: 80;\n  bottom: calc(1.25rem + env(safe-area-inset-bottom));\n  left: 50%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 0.5rem;\n  width: max-content;\n  max-width: min(28rem, calc(100vw - 2rem));\n  translate: -50% 0;\n  pointer-events: none;\n}\n\n.toast-slot {\n  display: contents;\n}\n\n/* A raised card in the theme's own colours, square (A976). */\n.toast {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  box-sizing: border-box;\n  max-width: 100%;\n  min-height: 2.5rem;\n  margin: 0;\n  padding: 0.5rem 1rem 0.5rem 0.875rem;\n  overflow-wrap: anywhere;\n  border: 1px solid var(--pm-border-strong);\n  border-radius: 0;\n  background: var(--pm-raised);\n  box-shadow: var(--pm-popover-shadow);\n  color: var(--pm-fg);\n  font-size: var(--pm-text-item);\n  line-height: var(--pm-leading-snug);\n  animation: pm-toast-in var(--pm-medium) var(--pm-ease);\n}\n\n/* Only a toast with controls takes the pointer: a text toast lets a click or drop through. */\n.toast:has(button, a) {\n  pointer-events: auto;\n}\n\n.toast .i {\n  flex: none;\n  color: var(--pm-muted);\n}\n\n/* A check for a success, in the accent; a warning for a refusal or failure, in danger. */\n.toast[data-tone='done'] .toast-glyph,\n.toast .toast-glyph[data-icon='check'] {\n  color: var(--pm-accent);\n}\n\n.toast[data-tone='error'] .toast-glyph,\n.toast .toast-glyph[data-icon='warning'] {\n  color: var(--pm-danger);\n}\n\n/* A toast with an action (A524): Undo after Move to Trash. */\n.toast-with-action {\n  padding-right: 0.25rem;\n}\n\n.toast-action,\n.toast-close {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  min-height: 2rem;\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  color: inherit;\n  font: inherit;\n  cursor: pointer;\n}\n\n.toast-action {\n  padding: 0 0.6rem;\n  color: var(--pm-accent);\n  font-weight: var(--pm-weight-semibold);\n}\n\n.toast-close {\n  width: 2rem;\n  color: var(--pm-muted);\n}\n\n.toast-close .i {\n  color: inherit;\n}\n\n.toast-action:hover,\n.toast-close:hover {\n  background: var(--pm-hover);\n}\n\n.toast-close:hover {\n  color: var(--pm-fg);\n}\n\n.toast-action:focus-visible,\n.toast-close:focus-visible {\n  outline: none;\n  box-shadow: var(--pm-ring);\n}\n\n@keyframes pm-toast-in {\n  from {\n    opacity: 0;\n    transform: translateY(8px);\n  }\n}\n\n/* Going: it fades. */\n.toast[data-leaving] {\n  opacity: 0;\n  transition: opacity var(--pm-fast) var(--pm-ease);\n}\n\n.note-main:focus {\n  outline: none;\n}\n\n/* Tooltips (T36, A189): one layer, after a control's data-tip (shell/Tooltip.tsx). */\n.tooltip {\n  position: fixed;\n  z-index: 120;\n  max-width: min(18rem, calc(100vw - 1rem));\n  padding: 0.3rem 0.55rem;\n  border-radius: 0;\n  background: var(--pm-fg);\n  box-shadow: var(--pm-popover-shadow);\n  color: var(--pm-bg);\n  font-family: var(--pm-font);\n  font-size: var(--pm-text-tooltip);\n  font-weight: var(--pm-weight-tooltip);\n  line-height: var(--pm-leading-tooltip);\n  pointer-events: none;\n  animation: pm-fade var(--pm-fast) var(--pm-ease);\n}\n\n/* Touch screens have no hover: a control's label is in its sheet, drawer or app bar instead. */\n@media (hover: none) {\n  .tooltip {\n    display: none;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .tooltip,\n  .toast {\n    animation: none;\n  }\n\n  .toast[data-leaving] {\n    opacity: 0;\n    transition: none;\n  }\n}\n\n@keyframes pm-rise {\n  from {\n    opacity: 0;\n    transform: translateY(4px);\n  }\n}\n\n@keyframes pm-pulse {\n  50% {\n    opacity: 0.35;\n  }\n}\n\n/*\n * An inline confirmation's question (ConfirmBlock, PEN-137): a line of its own, in the row\n * label's weight, above the sentence; in a row of buttons it takes the whole first line.\n */\n[role='alertdialog'] > .confirm-block-title {\n  flex-basis: 100%;\n  margin: 0 0 0.25rem;\n  color: var(--pm-fg);\n  font-weight: var(--pm-weight-row-label);\n}\n\n/* apps/web/src/theme/look-settings.css */\n/*\n * Settings → Look and Feel (PEN-146): Appearance, Sidebar, Note and Symbols. Appearance, Sidebar\n * and Note are two tabs, Settings (the controls in groups of rows) and Preview (a live preview of\n * what they change, A1633). The theme editor is its controls beside its preview; on a narrow\n * window (the page's own width under 40rem) the preview goes under them. Every colour is a token.\n */\n.lf-page {\n  container-type: inline-size;\n}\n\n.lf-split {\n  --lf-preview: 20rem;\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) var(--lf-preview);\n  gap: 1.5rem;\n  align-items: start;\n  margin-top: 1rem;\n}\n\n/*\n * Settings and Preview (A1633), as Android's Appearance draws them (A1619): two tabs across the\n * page under its header, each with its icon, a line above and below and one between. The one\n * shown has the page's background and the accent under it; the other is darker. They hold still\n * under the pinned header while the page scrolls under them.\n */\n.lf-tabs {\n  --lf-tab-off: color-mix(in oklab, var(--pm-bg), var(--pm-shadow-color) 5%);\n\n  position: sticky;\n  z-index: 3;\n  top: calc(var(--pm-hit) + 1px);\n  display: grid;\n  grid-auto-columns: minmax(0, 1fr);\n  grid-auto-flow: column;\n  margin-top: 1rem;\n  border-block: 1px solid var(--pm-border-soft);\n  background: var(--pm-bg);\n}\n\n:root[data-mode='dark'] .lf-tabs {\n  --lf-tab-off: color-mix(in oklab, var(--pm-bg), var(--pm-shadow-color) 25%);\n}\n\n.lf-tab {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.5rem;\n  min-height: var(--pm-hit);\n  padding: 0 1rem;\n  border: 0;\n  border-radius: 0;\n  background: var(--lf-tab-off);\n  color: var(--pm-muted);\n  font: inherit;\n  font-size: var(--pm-text-item);\n  font-weight: var(--pm-weight-semibold);\n  white-space: nowrap;\n  cursor: pointer;\n}\n\n.lf-tab + .lf-tab {\n  border-left: 1px solid var(--pm-border-soft);\n}\n\n.lf-tab:hover {\n  color: var(--pm-fg);\n}\n\n.lf-tab[aria-selected='true'] {\n  background: var(--pm-bg);\n  color: var(--pm-fg);\n}\n\n.lf-tab[aria-selected='true']::after {\n  position: absolute;\n  inset: auto 0 -1px;\n  height: 2px;\n  background: var(--pm-accent);\n  content: '';\n}\n\n.lf-tab:focus-visible {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: -2px;\n}\n\n.lf-tabpanel {\n  min-width: 0;\n  margin-top: 1rem;\n}\n\n.lf-tabpanel[hidden] {\n  display: none;\n}\n\n/* The Preview tab: a line naming what it shows, then the preview as large as the page allows. */\n.lf-preview-panel {\n  --preview-zoom-height: calc(100vh - 16rem);\n\n  display: grid;\n  gap: 0.75rem;\n}\n\n.lf-preview-panel > .lf-help {\n  margin: 0;\n  font-size: var(--pm-text-help);\n}\n\n.lf-preview-panel .app-preview {\n  margin: 0 auto;\n}\n\n.lf-controls {\n  min-width: 0;\n}\n\n/* A group's subhead, its rule running to the column's edge. */\n.lf-sub {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.35rem 0.5rem;\n  margin: 1.5rem 0 0.5rem;\n  color: var(--pm-fg);\n  font-size: var(--pm-text-group-head);\n  font-weight: var(--pm-weight-group-head);\n}\n\n.lf-sub::after {\n  flex: 1 1 2rem;\n  height: 1px;\n  background: var(--pm-border-soft);\n  content: '';\n}\n\n.lf-controls > .lf-sub:first-child {\n  margin-top: 0;\n}\n\n/*\n * The group's name, a heading inside the subhead (A1559). The subhead keeps the place and size\n * `.settings-section h3` gave it while it was the heading itself; the name inside only inherits.\n */\n.settings-section .lf-sub {\n  margin: 2rem 0 0.5rem;\n  font-size: var(--pm-text-lg);\n}\n\n.lf-sub > .lf-sub-name {\n  margin: 0;\n  font: inherit;\n}\n\n.lf-sub-hint {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n  font-weight: var(--pm-weight-help);\n}\n\n/*\n * A setting kept on this device alone (A1559): a laptop, its words in the tooltip. Beside the\n * row's label (`lf-row-name`) or after a group's name.\n */\n.lf-row-name {\n  display: inline-flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4rem;\n}\n\n.lf-scope {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  color: var(--pm-muted);\n  cursor: help;\n}\n\n.lf-scope:hover {\n  color: var(--pm-fg);\n}\n\n/* A bordered list of rows. */\n.lf-group {\n  min-width: 0;\n  margin: 0;\n  padding: 0;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n  list-style: none;\n}\n\n.lf-group > * + * {\n  border-top: 1px solid var(--pm-border-soft);\n}\n\n/* Two columns of rows (the title bar's buttons); one on a narrow page. */\n.lf-group-two {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);\n}\n\n.lf-group-two > * {\n  border-top: 1px solid var(--pm-border-soft);\n}\n\n.lf-group-two > :nth-child(-n + 2) {\n  border-top: 0;\n}\n\n.lf-group-two > :nth-child(even) {\n  border-left: 1px solid var(--pm-border-soft);\n}\n\n/* Each cell one line at any width: icon, name, then its switch at the end. */\n.lf-group-two > .lf-row {\n  flex-wrap: nowrap;\n}\n\n.lf-group-two > .lf-row > .lf-row-text {\n  flex: 1 1 0;\n}\n\n.lf-group-two > .lf-row > .lf-row-control {\n  flex: none;\n}\n\n/* A long name wraps beside its icon, never under it. */\n.lf-group-two .lf-row-label {\n  flex-wrap: nowrap;\n  align-items: flex-start;\n}\n\n.lf-group-two .lf-row-label > .i {\n  flex: none;\n  margin-top: 0.15rem;\n}\n\n.lf-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4rem 0.75rem;\n  min-height: var(--pm-control);\n  padding: 0.5rem 0.75rem;\n}\n\n.lf-row-text {\n  display: grid;\n  flex: 1 1 10rem;\n  gap: 0.15rem;\n  min-width: 0;\n}\n\n.lf-row-label {\n  display: inline-flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4rem;\n  color: var(--pm-fg);\n  font-size: var(--pm-text-row-label);\n  font-weight: var(--pm-weight-row-label);\n}\n\n.lf-row-label .i {\n  color: var(--pm-muted);\n}\n\n.lf-row-help {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n  line-height: var(--pm-leading-help);\n}\n\n.lf-row-control {\n  display: flex;\n  flex: 0 1 auto;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 0.5rem;\n  min-width: 0;\n  margin-left: auto;\n}\n\n.lf-row-control > .pm-select {\n  width: 12rem;\n}\n\n/* A row's own status or alert, under its help (SettingRow's `extra`). */\n.lf-row-note {\n  margin: 0.2rem 0 0;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n  line-height: var(--pm-leading-help);\n}\n\n.lf-row-note[role='alert'] {\n  color: var(--pm-danger);\n}\n\n/* A control's empty value (no hotkey). */\n.lf-none {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-item);\n}\n\n/* A choice that fills its row (Quick Capture's Saves To): the whole row is the radio's label. */\n.lf-choice {\n  cursor: pointer;\n}\n\n.lf-choice:hover {\n  background: var(--pm-hover);\n}\n\n.lf-choice input {\n  flex: none;\n  margin: 0;\n  accent-color: var(--pm-accent);\n}\n\n.lf-choice:has(input:focus-visible) {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: -2px;\n}\n\n.lf-help {\n  margin: 0.5rem 0 0;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n  line-height: var(--pm-leading-help);\n}\n\n.lf-actions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.5rem 0.75rem;\n  margin-top: 0.75rem;\n}\n\n.lf-actions > .lf-help {\n  margin: 0;\n}\n\n/* A switch: a native checkbox drawn as on and off. */\n.lf-switch {\n  position: relative;\n  flex: none;\n  width: 2.1rem;\n  height: 1.2rem;\n  margin: 0;\n  border: 1px solid var(--pm-border-strong);\n  background: var(--pm-sidebar);\n  cursor: pointer;\n  appearance: none;\n  -webkit-appearance: none;\n  transition:\n    background var(--pm-fast),\n    border-color var(--pm-fast);\n}\n\n.lf-switch::before {\n  position: absolute;\n  top: 2px;\n  left: 2px;\n  width: calc(1.2rem - 6px);\n  height: calc(1.2rem - 6px);\n  background: var(--pm-muted);\n  content: '';\n  transition: transform var(--pm-fast);\n}\n\n.lf-switch:checked {\n  border-color: var(--pm-accent);\n  background: var(--pm-accent);\n}\n\n.lf-switch:checked::before {\n  background: var(--pm-on-accent);\n  transform: translateX(0.9rem);\n}\n\n.lf-switch:focus-visible {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: 2px;\n}\n\n.lf-switch:disabled {\n  cursor: default;\n  opacity: 0.5;\n}\n\n/* An option under a row's name (Show Notebook Names under Quick Access). */\n.lf-suboption {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.35rem;\n  color: var(--pm-fg);\n  cursor: pointer;\n}\n\n.lf-suboption input {\n  margin: 0;\n  accent-color: var(--pm-accent);\n}\n\n/* − 10 + */\n.lf-stepper {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.15rem;\n}\n\n.lf-stepper-value {\n  min-width: 1.75rem;\n  font-size: var(--pm-text-item);\n  font-variant-numeric: tabular-nums;\n  text-align: center;\n}\n\n/* Fields turned on and off as chips; the checkbox covers its chip, so a click lands on it. */\n.lf-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n}\n\n.lf-chip {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  gap: 0.3rem;\n  min-height: var(--pm-control-sm);\n  padding: 0 0.65rem;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n  color: var(--pm-muted);\n  font-size: var(--pm-text-item);\n  transition:\n    background var(--pm-fast),\n    border-color var(--pm-fast),\n    color var(--pm-fast);\n}\n\n.lf-chip input {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  margin: 0;\n  cursor: pointer;\n  opacity: 0;\n}\n\n.lf-chip:hover {\n  border-color: var(--pm-border-strong);\n  color: var(--pm-fg);\n}\n\n.lf-chip:has(input:checked) {\n  border-color: var(--pm-accent-line);\n  background: var(--pm-accent-soft);\n  color: var(--pm-fg);\n}\n\n.lf-chip:has(input:checked) .i {\n  color: var(--pm-accent);\n}\n\n.lf-chip:has(input:focus-visible) {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: 2px;\n}\n\n.lf-chip:has(input:disabled) {\n  opacity: 0.6;\n}\n\n.lf-chip:has(input:disabled) input {\n  cursor: not-allowed;\n}\n\n/* Rows that reorder: a handle, and a line where a dragged row will land. */\n.lf-grip {\n  flex: none;\n  color: var(--pm-muted);\n  cursor: grab;\n}\n\n.lf-grip:active {\n  cursor: grabbing;\n}\n\n[data-reorder-id][data-dragging] {\n  opacity: 0.5;\n}\n\n[data-reorder-id][data-drop='before'] {\n  box-shadow: inset 0 2px 0 var(--pm-accent);\n}\n\n[data-reorder-id][data-drop='after'] {\n  box-shadow: inset 0 -2px 0 var(--pm-accent);\n}\n\n.lf-reorder-item > .lf-row {\n  padding-left: 0.35rem;\n}\n\n/* The preview beside the controls, in sight as the page scrolls, under the pinned header. */\n.lf-preview-col {\n  position: sticky;\n  top: calc(var(--pm-hit) + 0.75rem);\n  display: grid;\n  gap: 0.5rem;\n  min-width: 0;\n}\n\n.lf-label {\n  margin: 0;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-list-head);\n  font-weight: var(--pm-weight-list-head);\n}\n\n.lf-preview-col > .lf-help {\n  margin: 0;\n  font-size: var(--pm-text-help);\n}\n\n.lf-preview-col .app-preview,\n.lf-preview-col .theme-contrast {\n  margin: 0;\n}\n\n.lf-controls .theme-grid {\n  grid-template-columns: repeat(auto-fill, minmax(9.5rem, 1fr));\n  margin-top: 0.75rem;\n}\n\n/* The Sidebar's preview's frame (the Note's is AppPreview's), in the theme's colours. */\n.lf-preview {\n  overflow: hidden;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-bg);\n  color: var(--pm-fg);\n  font-family: var(--pm-font);\n}\n\n/*\n * Settings → Sidebar's preview (A1564): the sidebar itself, at its real size and own width on the\n * Preview tab (A1633), cut off at a height with its foot fading out, as a window's sidebar runs on.\n */\n.lf-sidebar-preview {\n  display: block;\n  width: max-content;\n  max-width: 100%;\n  max-height: min(40rem, calc(100vh - 16rem));\n  margin-inline: auto;\n  padding: 0;\n  background: var(--pm-sidebar);\n  mask-image: linear-gradient(to bottom, currentcolor 85%, transparent);\n}\n\n.lf-sidebar-preview > .sidebar {\n  width: var(--lf-sidebar-width);\n  border-right: 0;\n}\n\n/* Settings → Symbols (Show the Keys): each row its handle, keys, glyph, colour and Remove. */\n.symbol-list.lf-group {\n  display: block;\n  margin: 1rem 0;\n}\n\n.symbol-list.lf-group > .symbol-row {\n  flex-wrap: nowrap;\n  padding: 0.35rem 0.6rem 0.35rem 0.35rem;\n}\n\n.symbol-row .glyph-trigger {\n  justify-content: center;\n  width: 2.5rem;\n  padding: 0;\n}\n\n.symbol-row .colour-trigger {\n  justify-content: flex-start;\n  width: 9.5rem;\n}\n\n/* A list item's row (A1632): its icon where a glyph goes, then its name and what it does. */\n.symbol-row .symbol-kind-icon {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  width: 2.5rem;\n  height: var(--pm-control);\n}\n\n.symbol-row .symbol-kind-name {\n  flex: none;\n  width: 9.5rem;\n}\n\n.symbol-row .symbol-kind-does {\n  flex: 0 1 auto;\n  min-width: 0;\n  margin: 0;\n}\n\n/* An emoji's colour can't be changed (A1588): the note beside its disabled colour. */\n.symbol-row .symbol-colour-note {\n  flex: 0 1 auto;\n  min-width: 0;\n  margin: 0;\n}\n\n.symbol-row .symbol-actions {\n  margin-left: auto;\n}\n\n.symbol-foot {\n  flex-wrap: wrap;\n  gap: 0.5rem 0.75rem;\n}\n\n/* Add ▾ opens from the button's left edge: the column clips what hangs left of it (A1632). */\n.symbol-foot .menu {\n  right: auto;\n  left: 0;\n}\n\n.symbol-foot > .lf-help {\n  margin: 0;\n  font-variant-numeric: tabular-nums;\n}\n\n.symbol-foot-end {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.25rem;\n  margin-left: auto;\n}\n\n/* The Text group's rows. */\n.font-control {\n  display: grid;\n  gap: 0.25rem;\n  width: 12rem;\n}\n\n.font-control .pm-select {\n  width: 100%;\n}\n\n.lf-row .font-size-row {\n  flex-wrap: nowrap;\n}\n\n.lf-row .font-size-range {\n  width: 6.5rem;\n  min-width: 0;\n  flex: none;\n}\n\n@container (max-width: 40rem) {\n  .lf-split {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .lf-preview-col {\n    position: static;\n  }\n\n  .lf-group-two {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .lf-group-two > :nth-child(2) {\n    border-top: 1px solid var(--pm-border-soft);\n  }\n\n  .lf-group-two > :nth-child(even) {\n    border-left: 0;\n  }\n\n  .symbol-list.lf-group > .symbol-row {\n    flex-wrap: wrap;\n  }\n}\n\n@media (max-width: 700px), (pointer: coarse) {\n  .lf-row {\n    min-height: var(--pm-hit);\n  }\n\n  .lf-chip {\n    min-height: var(--pm-hit);\n  }\n}\n\n/*\n * The fonts at their real size (A1582), under a preview: each sample is the app's own text (a\n * type role's class, or the note's `.note-body .ProseMirror` and `.doc-title`), its label under\n * it. Nothing here sets a size: the samples take theirs from the roles and the note's scale.\n */\n.type-specimen {\n  display: grid;\n  gap: 0.75rem;\n  min-width: 0;\n  padding: 0.75rem 0.9rem;\n  border: 1px solid var(--pm-border-soft);\n  background: var(--pm-bg);\n  color: var(--pm-fg);\n}\n\n.type-specimen-group {\n  display: grid;\n  gap: 0.5rem;\n  min-width: 0;\n}\n\n.type-specimen-row {\n  display: grid;\n  gap: 0.1rem;\n  min-width: 0;\n}\n\n.type-specimen-row > :first-child {\n  min-width: 0;\n  margin: 0;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}\n\n.type-specimen-row [data-specimen-label] {\n  color: var(--pm-muted);\n}\n\n/* The sidebar's rows' size (the touch layout's step larger, A1561). */\n.type-specimen-sidebar {\n  font-size: var(--pm-text-sidebar-item);\n}\n\n/* The note's samples in the note's own rules, without a note's height or margins. */\n.type-specimen-note .ProseMirror {\n  display: grid;\n  gap: 0.5rem;\n  min-height: 0;\n}\n\n.type-specimen-note .ProseMirror > .type-specimen-row {\n  margin: 0;\n}\n\n.type-specimen-note .ProseMirror > .type-specimen-row > :first-child,\n.type-specimen-note .ProseMirror p {\n  margin: 0;\n}\n\n.type-specimen-note .doc-title {\n  field-sizing: initial;\n}\n\n/*\n * A preview that opens larger (A1589): one button over the inert preview, the magnifying glass\n * over a soft dim on hover and on keyboard focus; the dialog draws the preview as large as the\n * window leaves room for (`--preview-zoom-height`), at its real size at most.\n */\n.preview-zoom {\n  position: relative;\n  min-width: 0;\n}\n\n.preview-zoom-button {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  place-items: center;\n  padding: 0;\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  color: var(--pm-fg);\n  cursor: zoom-in;\n  transition: background-color var(--pm-fast) var(--pm-ease);\n}\n\n.preview-zoom-icon {\n  display: grid;\n  place-items: center;\n  width: 2.75rem;\n  height: 2.75rem;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n  box-shadow: var(--pm-shadow);\n  opacity: 0;\n  transform: scale(0.92);\n  transition:\n    opacity var(--pm-fast) var(--pm-ease),\n    transform var(--pm-fast) var(--pm-ease);\n}\n\n.preview-zoom-button:hover,\n.preview-zoom-button:focus-visible {\n  background: color-mix(in oklab, var(--pm-scrim) 55%, transparent);\n}\n\n.preview-zoom-button:hover .preview-zoom-icon,\n.preview-zoom-button:focus-visible .preview-zoom-icon {\n  opacity: 1;\n  transform: none;\n}\n\n.preview-zoom-overlay {\n  align-items: center;\n  padding: 1rem;\n}\n\n.dialog.preview-zoom-dialog {\n  width: min(100%, 68rem);\n  max-height: calc(100vh - 2rem);\n}\n\n.preview-zoom-body {\n  --preview-zoom-height: calc(100vh - 8rem);\n\n  min-height: 0;\n  padding: 1rem;\n  overflow: auto;\n  background: var(--pm-bg);\n}\n\n.badge-preview-places.large {\n  display: flex;\n  justify-content: center;\n  zoom: 2;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .preview-zoom-button,\n  .preview-zoom-icon {\n    transition: none;\n  }\n}\n\n/* apps/web/src/pages/settings.css */\n/* Settings (T36 layout): back to the notes, the sections beside the open one. */\n.settings-shell {\n  max-width: 64rem;\n  margin: 0 auto;\n  padding: max(1rem, env(safe-area-inset-top)) 1.5rem 4rem;\n}\n\n.settings-bar {\n  display: flex;\n  align-items: center;\n  min-height: var(--pm-bar);\n}\n\n.settings-layout {\n  display: grid;\n  grid-template-columns: 14rem minmax(0, 1fr);\n  gap: 2.5rem;\n  align-items: start;\n}\n\n.settings-nav {\n  /* An entry's padding, its icon and the gap after it: Analytics Data's entry is set in by them. */\n  --settings-nav-pad: 0.6rem;\n  --settings-nav-icon: 16px;\n  --settings-nav-gap: 0.6rem;\n\n  position: sticky;\n  top: 1rem;\n  display: grid;\n  gap: 2px;\n}\n\n.settings-nav a {\n  display: flex;\n  align-items: center;\n  gap: var(--settings-nav-gap);\n  min-height: var(--pm-control);\n  padding: 0 var(--settings-nav-pad);\n  border-radius: 0;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-item);\n  text-decoration: none;\n}\n\n.settings-nav a:hover {\n  background: var(--pm-hover);\n  color: var(--pm-fg);\n}\n\n.settings-nav a[aria-current='page'] {\n  background: var(--pm-active);\n  color: var(--pm-fg);\n  font-weight: var(--pm-weight-semibold);\n}\n\n.settings-nav a[aria-current='page'] .i {\n  color: var(--pm-accent);\n}\n\n.settings-content {\n  min-width: 0;\n}\n\n/* Search Settings over the nav (PEN-146). */\n.settings-side {\n  display: grid;\n  align-content: start;\n  gap: 0.75rem;\n  min-width: 0;\n}\n\n.settings-search {\n  position: relative;\n  display: flex;\n  align-items: center;\n}\n\n.settings-search > .i {\n  position: absolute;\n  left: 0.6rem;\n  color: var(--pm-muted);\n  pointer-events: none;\n}\n\n.settings-search > .input {\n  padding-left: 1.85rem;\n}\n\n/* The nav's five groups, each under its heading; This Mac's says it is not synced. */\n.settings-nav-group {\n  display: grid;\n  gap: 2px;\n}\n\n.settings-nav-group + .settings-nav-group {\n  margin-top: 0.75rem;\n}\n\n.settings-nav-heading {\n  margin: 0 0 0.15rem;\n  padding: 0 0.6rem;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-list-head);\n  font-weight: var(--pm-weight-list-head);\n}\n\n.settings-nav-scope {\n  font-weight: var(--pm-weight-regular);\n}\n\n/* The results while there is a query: each a label (its match marked) over its place. */\n.setting-results {\n  display: grid;\n  margin: 1rem 0 0;\n  padding: 0;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n  list-style: none;\n}\n\n.setting-results li + li {\n  border-top: 1px solid var(--pm-border-soft);\n}\n\n.setting-results a {\n  display: grid;\n  gap: 0.15rem;\n  padding: 0.6rem 0.8rem;\n  color: var(--pm-fg);\n  text-decoration: none;\n}\n\n.setting-results a:hover {\n  background: var(--pm-hover);\n}\n\n.setting-results a:focus-visible {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: -2px;\n}\n\n.setting-result-label {\n  font-size: var(--pm-text-row-label);\n  font-weight: var(--pm-weight-row-label);\n}\n\n.setting-result-label mark {\n  background: var(--pm-accent-soft);\n  color: inherit;\n}\n\n.setting-result-place {\n  font-size: var(--pm-text-meta);\n}\n\n/* The setting a result opened, marked for a moment on its page. */\n.settings-content [data-setting][data-found] {\n  outline: 2px solid var(--pm-accent-line);\n  outline-offset: -2px;\n  background: var(--pm-accent-softer);\n  transition: background-color var(--pm-fast);\n}\n\n/* This Mac's pages (GitHub, Semantic Search, Updates): their groups and cards apart. */\n.settings-content .settings-section > :is(.lf-group, .updates-card, .github-token) {\n  margin-top: 1rem;\n}\n\n.settings-content .settings-section > .lf-group + .lf-group {\n  margin-top: 1rem;\n}\n\n.settings-content .settings-section > .repo-sign-in {\n  margin-top: 1rem;\n}\n\n/* A progress bar (Semantic Search's indexing): a track, its fill, and the percentage. */\n.settings-progress {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  width: 15rem;\n  max-width: 100%;\n}\n\n.settings-progress-track {\n  position: relative;\n  flex: 1;\n  height: 6px;\n  overflow: hidden;\n  background: var(--pm-border);\n}\n\n.settings-progress-fill {\n  position: absolute;\n  inset: 0 auto 0 0;\n  background: var(--pm-accent);\n  transition: width var(--pm-fast);\n}\n\n.settings-progress-value {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-meta);\n  font-variant-numeric: tabular-nums;\n}\n\n/* Updates' version card: the version, its chip and Check Now, then the channel and last check. */\n.updates-card {\n  padding: 0.85rem 1rem;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n}\n\n.updates-card-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.5rem 0.75rem;\n}\n\n.updates-card-name {\n  font-size: var(--pm-text-group-head);\n  font-weight: var(--pm-weight-group-head);\n}\n\n.updates-card-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n  margin-left: auto;\n}\n\n.updates-card-line,\n.updates-card .updates-status {\n  margin: 0.35rem 0 0;\n  font-size: var(--pm-text-meta);\n}\n\n/* A segmented control's group inside a row: no frame of its own. */\n.seg-field {\n  min-width: 0;\n  margin: 0;\n  padding: 0;\n  border: 0;\n}\n\n.updates-whats-new .release-notes {\n  margin-top: 0;\n}\n\n/* Back and Forward before \"← Notes\" (T51, A943). */\n.settings-bar {\n  gap: 0.75rem;\n}\n\n/*\n * Settings scrolls only its content (T51, A942): the bar, the heading and the sections' list\n * stay put, and the list scrolls on its own only in a short window. The page fills the window\n * under anything above it (#root is a column the window's height); the content column scrolls,\n * its scrollbar at the window's edge, and the 64rem column stays centred by its gutters. A phone\n * keeps its sticky bar and its row of tabs over a page that scrolls (below).\n */\n@media (min-width: 701px) {\n  .settings-shell {\n    --settings-gutter: max(1.5rem, calc((100vw - 64rem) / 2 + 1.5rem));\n    display: flex;\n    flex: 1 1 0;\n    flex-direction: column;\n    min-height: 0;\n    max-width: none;\n    margin: 0;\n    padding: max(1rem, env(safe-area-inset-top)) 0 0;\n  }\n\n  .settings-bar {\n    flex: none;\n    padding-inline: var(--settings-gutter);\n  }\n\n  .settings-page {\n    display: flex;\n    flex: 1 1 0;\n    flex-direction: column;\n    min-height: 0;\n  }\n\n  .settings-layout {\n    flex: 1 1 0;\n    grid-template-rows: minmax(0, 1fr);\n    align-items: stretch;\n    min-height: 0;\n    padding-left: var(--settings-gutter);\n  }\n\n  .settings-nav {\n    position: static;\n    align-self: start;\n    max-height: 100%;\n    box-sizing: border-box;\n    overflow-y: auto;\n    padding: 2px 2px 1rem;\n  }\n\n  /* Search Settings stays over the nav; in a short window the nav alone scrolls (PEN-146). */\n  .settings-side {\n    display: flex;\n    flex-direction: column;\n    gap: 0.75rem;\n    min-height: 0;\n  }\n\n  .settings-side > .settings-search {\n    flex: none;\n    padding: 2px 2px 0;\n  }\n\n  .settings-side > .settings-nav {\n    flex: 0 1 auto;\n    align-self: stretch;\n    min-height: 0;\n    max-height: none;\n  }\n\n  .settings-content {\n    min-height: 0;\n    overflow-y: auto;\n    /* Room for focus rings at its left edge, which the scroll box would clip. */\n    margin-left: -4px;\n    padding: 0 var(--settings-gutter) 4rem 4px;\n  }\n\n  /* The pinned row runs to the content column's edges, its words where the page's are. */\n  .settings-head-bar {\n    margin-inline: -4px calc(-1 * var(--settings-gutter));\n    padding-inline: 4px var(--settings-gutter);\n  }\n}\n\n/*\n * Every page's header (A1560): \"Settings (i)\" in a row that pins to the top of the content\n * column, the page's title large under it, and one line. Scrolled past the title, the row takes\n * a hairline, a soft shadow and the title, small, after a slash. The row is the same height\n * either way, so nothing below it moves; only the crumb fades in.\n */\n.settings-head,\n.settings-head-bar {\n  --settings-page-title: var(--pm-text-page-title);\n  --settings-bar-title: var(--pm-text-bar-title);\n}\n\n.settings-head-bar {\n  position: sticky;\n  z-index: 4;\n  top: 0;\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n  min-height: var(--pm-hit);\n  border-bottom: 1px solid transparent;\n  background: var(--pm-bg);\n  transition:\n    border-color var(--pm-medium) var(--pm-ease),\n    box-shadow var(--pm-medium) var(--pm-ease);\n}\n\n.settings-head-bar[data-pinned] {\n  border-bottom-color: var(--pm-border-soft);\n  box-shadow: 0 2px 8px color-mix(in oklab, var(--pm-shadow-color) 6%, transparent);\n}\n\n.settings-head-root {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-md);\n}\n\n.settings-head-crumb {\n  display: inline-flex;\n  align-items: baseline;\n  gap: 0.6rem;\n  min-width: 0;\n  overflow: hidden;\n  color: var(--pm-fg);\n  font-size: var(--settings-bar-title);\n  font-weight: var(--pm-weight-bar-title);\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  visibility: hidden;\n  opacity: 0;\n  transform: translateY(0.3rem);\n  transition:\n    opacity var(--pm-medium) var(--pm-ease),\n    transform var(--pm-medium) var(--pm-ease),\n    visibility 0s linear var(--pm-medium);\n}\n\n.settings-head-bar[data-pinned] .settings-head-crumb {\n  visibility: visible;\n  opacity: 1;\n  transform: none;\n  transition:\n    opacity var(--pm-medium) var(--pm-ease),\n    transform var(--pm-medium) var(--pm-ease),\n    visibility 0s;\n}\n\n.settings-head-slash {\n  color: var(--pm-border-strong);\n  font-weight: var(--pm-weight-regular);\n}\n\n.settings-head {\n  margin: 0 0 1.25rem;\n}\n\n.settings-head-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.5rem 0.75rem;\n}\n\n.settings-head-title {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  min-width: 0;\n  margin: 0.15rem 0 0;\n  color: var(--pm-fg);\n  font-size: var(--settings-page-title);\n  font-weight: var(--pm-weight-page-title);\n  line-height: var(--pm-leading-page-title);\n  letter-spacing: -0.02em;\n}\n\n.settings-head-actions {\n  display: flex;\n  margin-left: auto;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.5rem;\n}\n\n.settings-head-intro {\n  margin: 0.35rem 0 0;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-body);\n  line-height: var(--pm-leading-body);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .settings-head-bar,\n  .settings-head-crumb,\n  .settings-head-bar[data-pinned] .settings-head-crumb {\n    transition: none;\n  }\n\n  .settings-head-crumb {\n    transform: none;\n  }\n}\n\n/* The (i): where settings are kept, in the tooltip's own colours, with a link that works. */\n.settings-info {\n  position: relative;\n  display: inline-flex;\n}\n\n.settings-info-button {\n  color: var(--pm-muted);\n}\n\n.settings-info-tip {\n  position: absolute;\n  z-index: 6;\n  top: calc(100% + 0.35rem);\n  left: -0.5rem;\n  width: max-content;\n  max-width: min(19rem, calc(100vw - 2rem));\n  padding: 0.55rem 0.7rem;\n  background: var(--pm-fg);\n  box-shadow: var(--pm-popover-shadow);\n  color: var(--pm-bg);\n  font-family: var(--pm-font);\n  font-size: var(--pm-text-sm);\n  font-weight: var(--pm-weight-tooltip);\n  line-height: var(--pm-leading-tooltip);\n  animation: pm-fade var(--pm-fast) var(--pm-ease);\n}\n\n.settings-info-tip[hidden] {\n  display: none;\n}\n\n.settings-info-tip a {\n  color: inherit;\n  font-weight: var(--pm-weight-semibold);\n  text-decoration: underline;\n  text-underline-offset: 2px;\n}\n\n.settings-info-laptop {\n  display: inline-flex;\n  vertical-align: -0.15em;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .settings-info-tip {\n    animation: none;\n  }\n}\n\n.settings-section h2,\n.settings > h2 {\n  margin: 0 0 0.35rem;\n  font-size: var(--pm-text-section-head);\n  font-weight: var(--pm-weight-section-head);\n  line-height: var(--pm-leading-section-head);\n}\n\n.settings-section > p {\n  margin: 0 0 0.8rem;\n}\n\n/* A section's explanations read the same in every section (T36). */\n.settings-content :is(.settings, .settings-section) > p {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-body);\n  line-height: var(--pm-leading-body);\n}\n\n/*\n * One rhythm for a section's controls (A988): each field, list of toggles or group of choices\n * starts 1.5rem under what is above it, and a hint sits 0.5rem under its control, in the\n * hint's size on every page. They were 13, 16 or 24px apart by kind, and a hint was 13 or 14px\n * and 0 to 16px under its control.\n */\n.settings-content\n  :is(.settings, .settings-section)\n  > :is(.settings-field, .display-toggles, .display-toggle) {\n  margin: 1.5rem 0 0;\n}\n\n.settings-content :is(.settings, .settings-section) > p.settings-help {\n  margin: 0.5rem 0 0;\n  font-size: var(--pm-text-help);\n  line-height: var(--pm-leading-help);\n}\n\n/* Sections stacked on one page (Status, Devices) stand as far apart; one touched the next. */\n.settings-content > section + section {\n  margin-top: 2rem;\n}\n\n.input,\n.app-shell input:not([type]) {\n  box-sizing: border-box;\n  width: 100%;\n  height: var(--pm-control);\n  padding: 0 0.65rem;\n  border: 1px solid var(--pm-border);\n  border-radius: 0;\n  background: var(--pm-raised);\n  color: var(--pm-fg);\n  font: inherit;\n  font-size: var(--pm-text-field);\n  font-weight: var(--pm-weight-regular);\n  transition:\n    border-color var(--pm-fast),\n    box-shadow var(--pm-fast);\n}\n\n.input:focus,\n.app-shell input:not([type]):focus {\n  border-color: var(--pm-accent-line);\n  outline: none;\n  box-shadow: var(--pm-ring);\n}\n\n.input:focus-visible {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: 0;\n}\n\n/*\n * The one select (T51 item 13, A941; packages/ui/src/controls/Select.tsx): a native select\n * with a text field's box and a chevron of its own, drawn as two strokes in the muted colour\n * so it follows the theme. `.pm-select-sm` for toolbars and filters; `.pm-select-quiet` shows\n * its frame only on hover and focus, inside something already framed.\n */\n.pm-select {\n  --pm-select-chevron: var(--pm-muted);\n  box-sizing: border-box;\n  width: 100%;\n  max-width: 100%;\n  height: var(--pm-control);\n  margin: 0;\n  padding: 0 1.75rem 0 0.65rem;\n  border: 1px solid var(--pm-border);\n  border-radius: 0;\n  background-color: var(--pm-raised);\n  background-image:\n    linear-gradient(\n      45deg,\n      transparent calc(50% - 0.75px),\n      var(--pm-select-chevron) calc(50% - 0.75px) calc(50% + 0.75px),\n      transparent calc(50% + 0.75px)\n    ),\n    linear-gradient(\n      135deg,\n      transparent calc(50% - 0.75px),\n      var(--pm-select-chevron) calc(50% - 0.75px) calc(50% + 0.75px),\n      transparent calc(50% + 0.75px)\n    );\n  background-position:\n    right 15px center,\n    right 10px center;\n  background-size: 5px 5px;\n  background-repeat: no-repeat;\n  color: var(--pm-fg);\n  font: inherit;\n  font-size: var(--pm-text-field);\n  font-weight: var(--pm-weight-regular);\n  line-height: normal;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  cursor: pointer;\n  appearance: none;\n  -webkit-appearance: none;\n  transition:\n    background-color var(--pm-fast),\n    border-color var(--pm-fast),\n    box-shadow var(--pm-fast);\n}\n\n.pm-select:hover:not(:disabled) {\n  --pm-select-chevron: var(--pm-fg);\n  border-color: var(--pm-border-strong);\n}\n\n.pm-select:focus {\n  border-color: var(--pm-accent-line);\n  outline: none;\n  box-shadow: var(--pm-ring);\n}\n\n.pm-select:focus-visible {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: 0;\n}\n\n.pm-select:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n\n.pm-select option,\n.pm-select optgroup {\n  background: var(--pm-raised);\n  color: var(--pm-fg);\n}\n\n.pm-select-sm {\n  width: auto;\n  height: var(--pm-control-sm);\n  padding: 0 1.5rem 0 0.5rem;\n  background-position:\n    right 12px center,\n    right 7px center;\n}\n\n.pm-select-quiet {\n  border-color: transparent;\n  background-color: transparent;\n  box-shadow: none;\n}\n\n.pm-select-quiet:hover:not(:disabled),\n.pm-select-quiet:focus {\n  border-color: var(--pm-border);\n  background-color: var(--pm-raised);\n}\n\n.chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.25rem;\n  padding: 0.1rem 0.5rem;\n  border: 1px solid transparent;\n  border-radius: 0;\n  background: var(--pm-accent-softer);\n  color: var(--pm-fg);\n  font-size: var(--pm-text-badge);\n  font-weight: var(--pm-weight-medium);\n}\n\n.kb-conflict,\n.kb-error,\n.kb-done {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4rem;\n  margin-top: 0.35rem;\n  font-size: var(--pm-text-help);\n  font-weight: var(--pm-weight-regular);\n}\n\n.kb-conflict,\n.kb-error {\n  color: var(--pm-danger);\n}\n\n.kb-done {\n  color: var(--pm-muted);\n}\n\n.kb-conflict .btn {\n  height: 1.6rem;\n}\n\n/*\n * A narrow window (PEN-146): the search over a row of tabs; the groups' headings go, and their\n * entries run on in the one row.\n */\n@media (max-width: 700px) {\n  .settings-nav-group {\n    display: contents;\n  }\n\n  .settings-nav-heading {\n    display: none;\n  }\n}\n\n/* apps/web/src/sources/sources.css */\n/* Git notebooks in the Mac app (T50 G3–G5, A862): the sidebar's sections, their sync state, and\n   Settings → Notebooks' cards. Tokens only (shell/base.css :root). */\n\n/*\n * A notebook's name is in the accent (T52), a quarter of the way to the text colour: plain accent\n * text is under 4.5:1 on some themes' sidebars (Nord and Solarized light). theme/contrast.ts\n * checks the same mix.\n */\n.sidebar {\n  --pm-notebook-name: color-mix(in oklab, var(--pm-accent), var(--pm-fg) 25%);\n}\n\n.sb-section + .sb-section {\n  margin-top: 0.25rem;\n  padding-top: 0.25rem;\n  border-top: 1px solid var(--pm-border-soft);\n}\n\n.sb-section-head {\n  display: flex;\n  align-items: center;\n  gap: 0.35rem;\n  min-width: 0;\n  padding: 0.15rem calc(var(--sb-gutter, 0rem) + 0.5rem) 0.15rem 0;\n}\n\n/* A section's title (A988): a heading holding its toggle, taking the row. */\n.sb-section-title {\n  display: flex;\n  flex: 1;\n  min-width: 0;\n  margin: 0;\n  font: inherit;\n}\n\n.sb-section-toggle {\n  display: flex;\n  flex: 1;\n  align-items: center;\n  gap: var(--sb-name-gap, 0.425rem);\n  min-width: 0;\n  padding: 0.2rem 0.3rem 0.2rem var(--sb-chevron-inset, 0.375rem);\n  border: 0;\n  border-radius: 0;\n  background: none;\n  color: var(--pm-muted);\n  font: inherit;\n  font-size: var(--pm-text-list-head);\n  font-weight: var(--pm-weight-list-head);\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n  cursor: pointer;\n}\n\n.sb-section-toggle:hover {\n  color: var(--pm-fg);\n}\n\n/* The chevron never gives way, however narrow the row: the name does (finding 19). */\n.sb-section-toggle > .i {\n  flex: none;\n}\n\n/* A notebook's own toggle keeps its colour; a hover shades the row instead (T52). */\n.sb-section-toggle.sb-notebook-name,\n.sb-section-toggle.sb-notebook-name:hover {\n  color: var(--pm-notebook-name);\n}\n\n/*\n * The whole row shades, its buttons and sync dot included, not the name alone (T62 item 3). A\n * button under the pointer shades twice as deep, so it still stands out on the shaded row.\n */\n.sb-source > .sb-section-head:hover {\n  background: var(--pm-hover);\n}\n\n/*\n * A notebook's buttons and sync dot sit flush with its row's end, each as tall as the row and\n * square, with no margin (feedback of 6 Nov 2026). The row keeps its height: the dot's 1.5rem\n * target and the 0.15rem it had above and below.\n */\n.sb-source > .sb-section-head {\n  --sb-head-height: 1.8rem;\n  container: sb-notebook-row / inline-size;\n  align-items: stretch;\n  min-height: var(--sb-head-height);\n  padding-block: 0;\n  padding-inline-end: 0;\n}\n\n/*\n * In a sidebar near its narrowest, the badge (PEN-140) and its gaps tighten, so the notebook's\n * name keeps room to be read beside the row's buttons (R2-21, finding 19).\n */\n@container sb-notebook-row (max-width: 15.5rem) {\n  .sb-source > .sb-section-head .sb-notebook-name {\n    gap: 0.2rem;\n    padding-inline-end: 0.1rem;\n  }\n\n  .sb-source > .sb-section-head .nb-badge.sb-source-badge {\n    inline-size: 1rem;\n    block-size: 1rem;\n    font-size: var(--pm-text-2xs);\n  }\n}\n\n.sb-source > .sb-section-head .tree-actions {\n  align-items: stretch;\n}\n\n.sb-source > .sb-section-head :is(.tree-actions .icon-btn, .sync-dot) {\n  width: var(--sb-head-height);\n  height: auto;\n}\n\n@media (max-width: 700px), (pointer: coarse) {\n  .sb-source > .sb-section-head {\n    --sb-head-height: var(--pm-hit);\n  }\n}\n\n.sb-source > .sb-section-head :is(.icon-btn, .sync-dot):hover {\n  background: color-mix(in oklab, var(--pm-fg) 13%, transparent);\n}\n\n.sb-section-toggle:focus-visible {\n  outline: 2px solid var(--pm-accent);\n  outline-offset: 1px;\n}\n\n.sb-section-name {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n/*\n * A source's sync state on its header (T51, A933): a dot alone, in the state's colour, with the\n * words as its tooltip and name. The link around it is a 24 px target (WCAG 2.2 target size).\n * Each kind of state has its own shape too (T52), so it never rests on colour alone, nor reads as\n * part of the name in the accent beside it: a solid dot when all is well or syncing, a ring when\n * offline, and a dot ringed with a gap when sync needs you.\n */\n.sync-dot {\n  display: inline-grid;\n  flex: none;\n  place-items: center;\n  width: 1.5rem;\n  height: 1.5rem;\n  border-radius: 0;\n  text-decoration: none;\n}\n\n.sync-dot:hover {\n  background: var(--pm-hover);\n}\n\n.sync-dot:focus-visible {\n  outline: 2px solid var(--pm-accent);\n  outline-offset: -2px;\n}\n\n.sync-dot .dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: var(--pm-accent);\n}\n\n.sync-dot:is([data-state='starting'], [data-state='syncing']) .dot {\n  animation: pm-pulse 1s ease-in-out infinite;\n}\n\n.sync-dot[data-state='offline'] .dot {\n  background: transparent;\n  box-shadow: inset 0 0 0 1.5px var(--pm-muted);\n}\n\n.sync-dot[data-state='stopped'] .dot {\n  width: 6px;\n  height: 6px;\n  background: var(--pm-danger);\n  outline: 1.5px solid var(--pm-danger);\n  outline-offset: 1.5px;\n}\n\n/*\n * Sync stopped (Ryan's review of #193, R2-5): the notebook's row is a band in the danger colour\n * with the page's colour as its text and icons, as the status bar's Sync Stopped (A1396), so it\n * is as legible as danger text on the page, which every theme's contrast checks hold to AA. The\n * dot is the status bar's (!). The band keeps its colour under the pointer; a button on it\n * shades with the text colour, which moves it away from the page colour in light and dark alike.\n */\n.sb-source > .sb-section-head[data-sync='stopped'],\n.sb-source > .sb-section-head[data-sync='stopped']:hover {\n  --pm-notebook-name: var(--pm-bg);\n  background: var(--pm-danger);\n  color: var(--pm-bg);\n}\n\n.sb-source > .sb-section-head[data-sync='stopped'] :is(.icon-btn, .sync-dot),\n.sb-source > .sb-section-head[data-sync='stopped'] .icon-btn[aria-expanded='true'] {\n  color: var(--pm-bg);\n}\n\n.sb-source > .sb-section-head[data-sync='stopped'] .icon-btn[aria-expanded='true'] {\n  background: color-mix(in oklab, var(--pm-fg) 13%, transparent);\n}\n\n.sb-source > .sb-section-head[data-sync='stopped'] :is(.sb-section-toggle, .icon-btn, .sync-dot) {\n  outline-color: var(--pm-bg);\n}\n\n.sync-dot[data-state='stopped'] .i {\n  color: currentColor;\n}\n\n.sb-section {\n  flex: none;\n  min-width: 0;\n}\n\n/* Settings → Notebooks. */\n.settings-card {\n  margin: 0 0 1rem;\n  padding: 0.85rem 1rem;\n  border: 1px solid var(--pm-border-soft);\n  border-radius: 0;\n  background: var(--pm-raised);\n}\n\n.settings-card > :is(h2, h3):first-child,\n.settings-card > header:first-child {\n  margin-top: 0;\n}\n\n/* A card's title with its icon (Agents → The penmoss Command), and its words at the rows' size. */\n.settings-card > h3 {\n  display: flex;\n  align-items: center;\n  gap: 0.45rem;\n}\n\n.settings-card > p {\n  font-size: var(--pm-text-body);\n}\n\n.settings-facts {\n  display: grid;\n  grid-template-columns: max-content minmax(0, 1fr);\n  gap: 0.35rem 1.25rem;\n  margin: 0 0 0.85rem;\n  font-size: var(--pm-text-body);\n}\n\n.settings-facts dt {\n  color: var(--pm-muted);\n}\n\n.settings-facts dd {\n  margin: 0;\n  color: var(--pm-fg);\n  overflow-wrap: anywhere;\n}\n\n.git-notebook [data-testid='git-error'] {\n  color: var(--pm-danger);\n}\n\n.settings-card .settings-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-end;\n  gap: 0.6rem 1rem;\n  margin: 0.6rem 0 0;\n}\n\n.settings-card .settings-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n  margin: 0.6rem 0 0;\n}\n\n/* Rename Notebook on a notebook's row (Ryan's review of PR #192): its name, edited in place. */\n.sb-section-rename {\n  display: flex;\n  flex: 1;\n  align-items: center;\n  gap: var(--sb-name-gap, 0.425rem);\n  min-width: 0;\n  padding: 0.2rem 0.3rem 0.2rem var(--sb-chevron-inset, 0.375rem);\n  color: var(--pm-notebook-name);\n}\n\n/* What Rename says under the row: that it renames it everywhere, or a name already in use. */\n.sb-section-clash {\n  margin: 0.25rem 0.5rem 0.4rem;\n  font-size: var(--pm-text-meta);\n}\n\n/* A name another notebook on this Mac has (add and Rename): a free one to use instead. */\n.name-clash {\n  margin: 0.5rem 0 0;\n  padding: 0.55rem 0.7rem;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-warn-bg);\n  border-radius: 0;\n}\n\n.name-clash p {\n  margin: 0;\n}\n\n.name-clash-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n  margin-top: 0.5rem;\n}\n\n/* Settings → Notebooks → the notebook's Name: the field and Rename side by side. */\n.git-notebook-rename {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-end;\n  gap: 0.5rem;\n}\n\n/* Remove with changes not pushed: what would be lost, and the way to keep it. */\n.git-remove-confirm {\n  margin: 0.75rem 0 0;\n  padding: 0.65rem 0.8rem;\n  border: 1px solid var(--pm-danger);\n  border-radius: 0;\n}\n\n.git-remove-confirm p {\n  margin: 0;\n}\n\n/* Delete for good to confirm again: the notes it takes, named before Touch ID. */\n.git-reconfirm {\n  margin: 0.5rem 0 0;\n  padding: 0.65rem 0.8rem;\n  border: 1px solid var(--pm-danger);\n  border-radius: 0;\n  color: var(--pm-fg);\n}\n\n.git-reconfirm p,\n.git-reconfirm ul {\n  margin: 0 0 0.4rem;\n}\n\n/*\n * Settings → Notebooks lists the notebooks, and each opens a page of its own (Ryan's\n * feedback, 5 Nov 2026; A1098): a row with the name, the repository under it and the sync state.\n */\n.git-notebook-list {\n  margin: 0.25rem 0 1rem;\n  padding: 0;\n  border: 1px solid var(--pm-border-soft);\n  background: var(--pm-raised);\n  list-style: none;\n}\n\n.git-notebook-list > li + li {\n  border-top: 1px solid var(--pm-border-soft);\n}\n\n.git-notebook-row {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  padding: 0.6rem 0.85rem;\n  color: var(--pm-fg);\n  text-decoration: none;\n}\n\n.git-notebook-row:hover {\n  background: var(--pm-hover);\n}\n\n.git-notebook-row:focus-visible {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: -2px;\n}\n\n.git-notebook-row > .i {\n  flex: none;\n  color: var(--pm-muted);\n}\n\n.git-notebook-row-text {\n  display: flex;\n  flex: 1;\n  flex-direction: column;\n  min-width: 0;\n}\n\n.git-notebook-row-name {\n  font-size: var(--pm-text-row-label);\n  font-weight: var(--pm-weight-row-label);\n}\n\n.git-notebook-row-repo {\n  overflow: hidden;\n  font-size: var(--pm-text-meta);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.git-notebook-row-state {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  gap: 0.35rem;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-meta);\n}\n\n.git-notebook-row-state .dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: var(--pm-accent);\n}\n\n.git-notebook-row-state[data-phase='offline'] .dot {\n  background: transparent;\n  box-shadow: inset 0 0 0 1.5px var(--pm-muted);\n}\n\n.git-notebook-row-state[data-phase='stopped'] {\n  color: var(--pm-danger);\n}\n\n.git-notebook-row-state[data-phase='stopped'] .dot {\n  background: var(--pm-danger);\n}\n\n.git-message:empty {\n  display: none;\n}\n\n.git-message {\n  margin: 0.5rem 0 0;\n  font-size: var(--pm-text-help);\n}\n\n/* Commits and Access: each field a line of its own, one width, its buttons under it. */\n.git-notebook-form {\n  display: grid;\n  max-width: 30rem;\n}\n\n.git-notebook-form > .settings-field {\n  margin: 0 0 0.75rem;\n}\n\n.git-notebook-form .settings-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n  margin: 0;\n}\n\n.git-notebook-form > [data-testid='git-author-now'] {\n  margin: 0.6rem 0 0;\n  font-size: var(--pm-text-help);\n}\n\n.git-notebook-row-name {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n\n/* Settings → Agents (PEN-146): a notebook unfolded, its agents under its row. */\n.notebook-agents .local-agents {\n  margin-top: 0.5rem;\n  padding-top: 0.5rem;\n}\n\n/* Agents on This Mac and the penmoss command (T54, A992, A993). */\n.local-agents {\n  margin: 1rem 0 0;\n  padding: 0.75rem 0 0;\n  border-top: 1px solid var(--pm-border);\n}\n\n.local-agents > h4 {\n  margin: 0 0 0.4rem;\n}\n\n.local-agents > p {\n  margin: 0 0 0.5rem;\n}\n\n.local-agent-list {\n  display: grid;\n  gap: 0.85rem;\n  margin: 0.6rem 0 0;\n  padding: 0;\n  list-style: none;\n}\n\n.local-agent-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4rem 0.75rem;\n}\n\n.local-agent-head .btn {\n  margin-left: auto;\n}\n\n/* T60 (A1073): the switch that shows the Claude Code command with its channel. */\n.local-agent-channel {\n  display: flex;\n  align-items: center;\n  gap: 0.45rem;\n  margin: 0.45rem 0 0;\n  font-size: var(--pm-text-item);\n}\n\n.local-agent-copy {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) auto;\n  gap: 0.25rem 0.5rem;\n  align-items: start;\n  margin: 0.45rem 0 0;\n}\n\n.local-agent-copy > span {\n  grid-column: 1 / -1;\n  font-size: var(--pm-text-item);\n}\n\n.local-agent-copy > span:empty {\n  display: none;\n}\n\n.local-agent-copy pre {\n  margin: 0;\n  padding: 0.45rem 0.6rem;\n  overflow-x: auto;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n  font-family: var(--pm-mono);\n  font-size: var(--pm-text-code);\n  line-height: var(--pm-leading-code);\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  user-select: text;\n}\n\n.local-agent-direct {\n  margin: 0.6rem 0 0;\n}\n\n.local-agent-direct summary {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-item);\n  cursor: default;\n}\n\n/*\n * The first run (T59, A1030; Ryan's review of #192, findings 2–4, First Run C): no git notebook\n * yet, so the window holds one screen at a time, a column in the middle of it: the \"Step n of 3\"\n * bar, a title, the one thing the screen asks, and a footer with Back and its button.\n */\n.first-run {\n  display: flex;\n  box-sizing: border-box;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  min-height: 100%;\n  padding: 1.5rem 1rem;\n}\n\n.first-run-plain {\n  max-width: 34rem;\n}\n\n/* The flow's screen stack: the screen itself is the column's child. */\n.fr-steps {\n  display: contents;\n}\n\n/*\n * Add Notebook from Settings (A1562): the first run's screens over Settings, on the dialogs' scrim,\n * the card in the middle as on the first run. It scrolls itself when the window is short.\n */\n.fr-sheet {\n  position: fixed;\n  inset: 0;\n  z-index: 60;\n  overflow: auto;\n  background: var(--pm-scrim);\n}\n\n.fr-sheet > .first-run {\n  min-height: 100%;\n}\n\n.fr-screen {\n  display: flex;\n  box-sizing: border-box;\n  flex-direction: column;\n  width: min(100%, 30rem);\n  min-height: min(36rem, calc(100vh - 6rem));\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n  box-shadow: var(--pm-shadow);\n  font-size: var(--pm-text-body);\n  /* A page's title in a card this size is a step smaller, as on a phone (A1561). */\n  --pm-text-page-title: var(--pm-text-3xl);\n}\n\n.fr-body {\n  display: flex;\n  flex: 1 1 auto;\n  flex-direction: column;\n  gap: 0.8rem;\n  min-width: 0;\n  padding: 1.25rem 1.6rem 1.4rem;\n}\n\n.fr-centered {\n  justify-content: center;\n  gap: 0.9rem;\n  padding-bottom: 2.5rem;\n}\n\n.fr-screen h2 {\n  margin: 0;\n  font-size: var(--pm-text-page-title);\n  font-weight: var(--pm-weight-page-title);\n  letter-spacing: -0.01em;\n  line-height: var(--pm-leading-page-title);\n}\n\n.fr-screen h2:focus {\n  outline: none;\n}\n\n.fr-brand {\n  display: flex;\n}\n\n.fr-foot {\n  display: flex;\n  flex: none;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 0.5rem;\n  padding: 0.75rem 1.6rem;\n  border-top: 1px solid var(--pm-border-soft);\n}\n\n.fr-actions {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n  gap: 0.4rem;\n  margin-inline-start: auto;\n}\n\n.fr-progress {\n  display: grid;\n  gap: 0.45rem;\n}\n\n.fr-step {\n  margin: 0;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-list-head);\n  font-weight: var(--pm-weight-list-head);\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n\n.fr-bars {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 4px;\n}\n\n.fr-bars > span {\n  height: 3px;\n  background: var(--pm-border);\n}\n\n.fr-bars > .on {\n  background: var(--pm-accent);\n}\n\n.fr-lead {\n  margin: 0;\n  color: var(--pm-muted);\n  line-height: var(--pm-leading-body);\n}\n\n.fr-welcome {\n  font-size: var(--pm-text-body);\n}\n\n.fr-small {\n  font-size: var(--pm-text-help);\n}\n\n/* A button that reads as a link (Try Again, Use field-notes-2, Start One Here). */\n.fr-link {\n  display: inline;\n  align-self: flex-start;\n  padding: 0;\n  border: 0;\n  background: none;\n  font: inherit;\n  text-decoration: underline;\n  text-underline-offset: 2px;\n  cursor: pointer;\n}\n\n.fr-learn,\n.fr-link {\n  color: var(--pm-link);\n  font-size: var(--pm-text-item);\n}\n\n/* Inside a line of words, a link is the line's size. */\n:is(.fr-lead, .fr-warn, .fr-invalid-words, .fr-tree-none) .fr-link {\n  align-self: auto;\n  font-size: inherit;\n}\n\n/* The choices of 1.2 and 1.3: wide rows, each a radio button. */\n.fr-options {\n  display: grid;\n  gap: 0.5rem;\n}\n\n.fr-option {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  min-height: 3.4rem;\n  padding: 0.6rem 0.9rem;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n  cursor: pointer;\n}\n\n.fr-option:hover {\n  border-color: var(--pm-border-strong);\n}\n\n.fr-option:has(input:checked) {\n  border-color: var(--pm-accent);\n  background: var(--pm-accent-softer);\n  box-shadow: inset 0 0 0 1px var(--pm-accent);\n}\n\n.fr-option:has(input:focus-visible),\n.fr-choice:has(input:focus-visible) {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: 2px;\n}\n\n.fr-option input,\n.fr-choice input {\n  flex: none;\n  width: 16px;\n  height: 16px;\n  margin: 0;\n  accent-color: var(--pm-accent);\n}\n\n.fr-option-text {\n  display: grid;\n  flex: 1;\n  gap: 0.1rem;\n  min-width: 0;\n}\n\n.fr-option-text strong {\n  font-weight: var(--pm-weight-semibold);\n}\n\n.fr-option-text > span {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n}\n\n/*\n * The account switcher above Pick Repository and Create New Repo (option 2, A1617): the account\n * as a wide button, its menu as wide as it.\n */\n.menu-anchor:has(> .fr-switcher) {\n  display: grid;\n}\n\n.fr-switcher {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  min-height: 3.4rem;\n  padding: 0.55rem 0.9rem;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n  color: var(--pm-fg);\n  font: inherit;\n  text-align: left;\n  cursor: pointer;\n}\n\n.fr-switcher:hover,\n.fr-switcher[aria-expanded='true'] {\n  border-color: var(--pm-border-strong);\n}\n\n.fr-switcher:focus-visible {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: 2px;\n}\n\n.fr-switcher > .i {\n  color: var(--pm-muted);\n}\n\n.fr-switcher-initial {\n  display: grid;\n  flex: none;\n  place-items: center;\n  width: 2rem;\n  height: 2rem;\n  background: var(--pm-accent);\n  color: var(--pm-on-accent);\n  font-weight: var(--pm-weight-semibold);\n}\n\n.fr-switcher-text {\n  display: grid;\n  flex: 1;\n  gap: 0.1rem;\n  min-width: 0;\n}\n\n.fr-switcher-text strong {\n  overflow: hidden;\n  font-weight: var(--pm-weight-semibold);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.fr-switcher-text > span {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n}\n\n.menu-anchor > .fr-switcher ~ .menu {\n  left: 0;\n}\n\n.menu-item .fr-switcher-line {\n  margin-left: 0.6rem;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n}\n\n/* Work going on, and what went wrong. */\n.fr-status {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  margin: 0;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-meta);\n}\n\n.fr-spin {\n  box-sizing: border-box;\n  flex: none;\n  width: 14px;\n  height: 14px;\n  border: 2px solid var(--pm-border);\n  border-top-color: var(--pm-accent);\n  border-radius: 50%;\n  animation: fr-spin 0.8s linear infinite;\n}\n\n.btn.primary .fr-spin {\n  border-color: color-mix(in oklab, var(--pm-on-accent) 40%, transparent);\n  border-top-color: var(--pm-on-accent);\n}\n\n.fr-spin-lg {\n  width: 18px;\n  height: 18px;\n}\n\n@keyframes fr-spin {\n  to {\n    transform: rotate(1turn);\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .fr-spin {\n    animation-duration: 2.4s;\n  }\n}\n\n.fr-error {\n  display: flex;\n  gap: 0.5rem;\n  margin: 0;\n  padding: 0.6rem 0.75rem;\n  border: 1px solid color-mix(in oklab, var(--pm-danger) 35%, transparent);\n  background: var(--pm-danger-soft);\n  line-height: var(--pm-leading-snug);\n}\n\n.fr-error > .i {\n  flex: none;\n  margin-top: 0.1rem;\n  color: var(--pm-danger);\n}\n\n.fr-ok {\n  margin: 0;\n  padding: 0.75rem;\n  border: 1px solid color-mix(in oklab, var(--pm-accent) 35%, transparent);\n  background: var(--pm-accent-softer);\n}\n\n.fr-empty {\n  margin: 0;\n  padding: 1.75rem 1rem;\n  border: 1px dashed var(--pm-border-strong);\n  color: var(--pm-muted);\n  text-align: center;\n}\n\n/* The device code (2.4): large enough to read across a desk, and copied whole. */\n.fr-code {\n  display: block;\n  padding: 1rem;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-bg);\n  font-family: var(--pm-mono);\n  font-size: var(--pm-text-display);\n  font-weight: var(--pm-weight-display);\n  line-height: var(--pm-leading-none);\n  letter-spacing: 0.12em;\n  text-align: center;\n  user-select: all;\n}\n\n.fr-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4rem;\n}\n\n/* Copy Code and Open GitHub's Page, side by side, each half the row. */\n.fr-row.fr-even > .btn {\n  flex: 1 1 0;\n}\n\n.fr-grow {\n  flex: 1 1 8rem;\n  min-width: 0;\n}\n\n/* Fields: the settings field, without its margins. */\n.fr-form,\n.fr-fields {\n  display: grid;\n  gap: 0.8rem;\n  min-width: 0;\n  margin: 0;\n  padding: 0;\n  border: 0;\n}\n\n.fr-screen .fr-field {\n  margin: 0;\n}\n\n.fr-field .input {\n  width: 100%;\n  box-sizing: border-box;\n}\n\n/*\n * The card is the raised colour, as a field is, so a field on it read as none (Ryan's review of\n * #193): every field on the card takes the page's colour and a stronger edge, in either theme.\n */\n.fr-screen :is(.input, .pm-select) {\n  background-color: var(--pm-bg);\n}\n\n.fr-screen :is(.input, .pm-select):not(:focus, .fr-invalid) {\n  border-color: var(--pm-border-strong);\n}\n\n.fr-repo-name {\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-weight: var(--pm-weight-regular);\n}\n\n.fr-facts {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.5rem;\n  font-size: var(--pm-text-meta);\n  font-weight: var(--pm-weight-regular);\n}\n\n.fr-owner {\n  font-weight: var(--pm-weight-regular);\n}\n\n.input.fr-invalid {\n  border-color: var(--pm-danger);\n}\n\n.fr-invalid-words {\n  color: var(--pm-danger);\n  font-size: var(--pm-text-help);\n  font-weight: var(--pm-weight-regular);\n}\n\n.fr-warn {\n  padding: 0.4rem 0.5rem;\n  background: var(--pm-warn-bg);\n  font-size: var(--pm-text-help);\n  font-weight: var(--pm-weight-regular);\n}\n\n.fr-more > summary {\n  color: var(--pm-link);\n  font-size: var(--pm-text-item);\n  cursor: pointer;\n}\n\n.fr-more .settings-field {\n  margin: 0.6rem 0 0;\n}\n\n/* Where a notebook is or goes: its folder and branch, each with its icon. */\n.fr-loc {\n  display: inline-flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.6rem;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-meta);\n  font-weight: var(--pm-weight-regular);\n}\n\n.fr-loc > span {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.25rem;\n}\n\n.fr-card {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  padding: 0.75rem;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-bg);\n  overflow-wrap: anywhere;\n}\n\n.fr-card-icon {\n  display: flex;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  width: 30px;\n  height: 30px;\n  background: var(--pm-accent-soft);\n  color: var(--pm-accent);\n}\n\n.fr-card-text {\n  display: grid;\n  gap: 0.15rem;\n  min-width: 0;\n}\n\n.fr-card-title {\n  font-weight: var(--pm-weight-semibold);\n}\n\n.fr-or {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  margin: 0.2rem 0 0;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-meta);\n}\n\n.fr-or > span {\n  flex: 1;\n  height: 1px;\n  background: var(--pm-border);\n}\n\n.fr-another {\n  display: grid;\n  gap: 0.5rem;\n}\n\n/* Use Existing Repo (4.2): each repository, the notebooks in it beneath (Notebook List A). */\n.fr-filter {\n  position: relative;\n  display: block;\n}\n\n.fr-filter > .i {\n  position: absolute;\n  top: 50%;\n  left: 0.6rem;\n  color: var(--pm-muted);\n  transform: translateY(-50%);\n}\n\n.fr-filter > .input {\n  width: 100%;\n  box-sizing: border-box;\n  padding-left: 1.9rem;\n}\n\n.fr-tree,\n.fr-tree-in {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n/* The count above the tree keeps its line whatever it says, so the tree never moves under it. */\n.fr-count {\n  min-height: 1lh;\n}\n\n.fr-tree {\n  box-sizing: border-box;\n  max-height: 22rem;\n  overflow-y: auto;\n  border: 1px solid var(--pm-border);\n}\n\n.fr-tree-repo,\n.fr-tree-notebook,\n.fr-tree-none {\n  display: flex;\n  align-items: center;\n  gap: 0.45rem;\n  min-width: 0;\n  border-bottom: 1px solid var(--pm-border-soft);\n}\n\n.fr-tree > li:last-child > :last-child,\n.fr-tree > li:last-child .fr-tree-in > li:last-child {\n  border-bottom: 0;\n}\n\n.fr-tree-repo {\n  min-height: 2rem;\n  padding: 0 0.6rem 0 0.25rem;\n  background: var(--pm-bg);\n  font-size: var(--pm-text-item);\n}\n\n.fr-tree-toggle {\n  display: flex;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  width: 1.5rem;\n  height: 1.5rem;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: var(--pm-muted);\n  cursor: pointer;\n}\n\n.fr-tree-name {\n  min-width: 0;\n  padding: 0.2rem 0;\n  overflow: hidden;\n  border: 0;\n  background: none;\n  color: var(--pm-fg);\n  font: inherit;\n  text-align: start;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  cursor: pointer;\n}\n\n.fr-tree-name:hover:not(:disabled) strong {\n  text-decoration: underline;\n}\n\n.fr-tree-name:disabled,\n.fr-tree-toggle:disabled {\n  color: var(--pm-muted);\n  cursor: not-allowed;\n}\n\n.fr-tree-name strong {\n  font-weight: var(--pm-weight-semibold);\n}\n\n/* What the filter matched (4.3). */\n.fr-tree mark {\n  background: var(--pm-highlight-bg);\n  color: inherit;\n}\n\n.fr-chip {\n  flex: none;\n  background: color-mix(in oklab, var(--pm-fg) 6%, transparent);\n  color: var(--pm-muted);\n}\n\n.fr-when {\n  flex: none;\n  margin-inline-start: auto;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-meta);\n  white-space: nowrap;\n}\n\n.fr-tree-notebook {\n  min-height: 2.4rem;\n  padding: 0.2rem 0.6rem 0.2rem 2rem;\n  cursor: default;\n}\n\n.fr-tree-notebook > .i {\n  flex: none;\n  color: var(--pm-accent);\n}\n\n.fr-tree-notebook > strong {\n  min-width: 0;\n  overflow: hidden;\n  font-weight: var(--pm-weight-semibold);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.fr-tree-notebook > .btn {\n  height: var(--pm-control-sm);\n  margin-inline-start: auto;\n}\n\n.fr-tree-notebook.on {\n  background: var(--pm-accent-softer);\n}\n\n.fr-tree-none {\n  min-height: 1.9rem;\n  padding: 0 0.6rem 0 2rem;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n}\n\n.fr-tree-none > span:not(.fr-spin) {\n  flex: 1;\n}\n\n/* Several notebooks (4.7) and Pick Folder (4.8): one row each, a radio button. */\n.fr-choices {\n  display: grid;\n  border: 1px solid var(--pm-border);\n}\n\n.fr-choice {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  min-height: 2.5rem;\n  padding: 0.35rem 0.75rem;\n  font-size: var(--pm-text-item);\n  border-bottom: 1px solid var(--pm-border-soft);\n  cursor: pointer;\n}\n\n.fr-choice:last-child {\n  border-bottom: 0;\n}\n\n.fr-choice:has(input:checked) {\n  background: var(--pm-accent-softer);\n}\n\n.fr-choice > .i {\n  flex: none;\n  color: var(--pm-muted);\n}\n\n.fr-choice-text {\n  display: grid;\n}\n\n.fr-choice-text strong {\n  font-weight: var(--pm-weight-semibold);\n}\n\n.fr-choice-text .muted {\n  font-size: var(--pm-text-help);\n}\n\n/* Setting Up (7.1, 7.3): each part of the work, done, going or failed. */\n.fr-checklist {\n  display: grid;\n  gap: 0.75rem;\n  margin: 0.2rem 0 0;\n  padding: 0;\n  list-style: none;\n}\n\n.fr-checklist > li {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n}\n\n.fr-checklist > li[data-mark='todo'] {\n  color: var(--pm-muted);\n}\n\n.fr-mark {\n  display: flex;\n  box-sizing: border-box;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  width: 18px;\n  height: 18px;\n  border-radius: 50%;\n}\n\n.fr-mark-done {\n  background: var(--pm-accent);\n  color: var(--pm-on-accent);\n}\n\n.fr-mark-failed {\n  background: var(--pm-danger);\n  color: var(--pm-on-accent);\n}\n\n.fr-mark-todo {\n  border: 2px solid var(--pm-border);\n}\n\n@media (max-width: 480px) {\n  .first-run {\n    justify-content: flex-start;\n    padding: 0;\n  }\n\n  .fr-screen {\n    min-height: 100%;\n    border: 0;\n    box-shadow: none;\n  }\n\n  .fr-body,\n  .fr-foot {\n    padding-inline: 1rem;\n  }\n}\n\n.boot {\n  max-width: 40rem;\n  margin: 0 auto;\n  padding: max(3rem, env(safe-area-inset-top)) 1rem 3rem;\n  color: var(--pm-muted);\n}\n\n/* Search: which notebook a hit is in. */\n.search-notebook {\n  padding: 0 0.4rem;\n  border-radius: 0;\n  background: var(--pm-raised);\n  color: var(--pm-fg);\n  font-weight: var(--pm-weight-semibold);\n}\n\n@media (max-width: 640px) {\n  .settings-facts {\n    grid-template-columns: minmax(0, 1fr);\n    gap: 0.1rem;\n  }\n\n  .settings-facts dd {\n    margin-bottom: 0.4rem;\n  }\n}\n\n/* Sign in with GitHub (T82, A1170): the code to enter, large enough to read across a desk. */\n.repo-sign-in {\n  display: grid;\n  gap: 0.5rem;\n  min-width: 0;\n  margin-block: 0.5rem;\n  padding: 0.75rem;\n  border: 1px solid var(--pm-border);\n}\n\n.repo-sign-in > p {\n  margin: 0;\n}\n\n.repo-sign-in-code {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.6rem;\n}\n\n.repo-sign-in-code code {\n  font-size: var(--pm-text-display);\n  font-weight: var(--pm-weight-display);\n  letter-spacing: 0.12em;\n  user-select: all;\n}\n\n/* Pick Folder (4.8; A1620, A1703): the tree with a filter, as Android draws it. */\n.fr-strip {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 0.75rem;\n  padding: 0.6rem 1.6rem;\n  border-top: 1px solid var(--pm-border-soft);\n}\n\n.fr-strip-text {\n  display: grid;\n  flex: 1 1 auto;\n  min-width: 0;\n}\n\n.fr-strip-label {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-meta);\n  font-weight: var(--pm-weight-meta);\n}\n\n.fr-strip-text code {\n  overflow: hidden;\n  font-family: var(--pm-mono);\n  font-size: var(--pm-text-help);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.fr-strip .fr-link {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  gap: 0.3rem;\n}\n\n.fr-filter-clear {\n  position: absolute;\n  top: 50%;\n  right: 0.25rem;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 1.75rem;\n  height: 1.75rem;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: var(--pm-muted);\n  cursor: pointer;\n  transform: translateY(-50%);\n}\n\n.fr-filter-clear:hover {\n  color: var(--pm-fg);\n}\n\n/* Room for the × (and no second, native one). */\n.fr-filter:has(.fr-filter-clear) > .input {\n  padding-right: 2rem;\n}\n\n.fr-filter > .input::-webkit-search-cancel-button {\n  appearance: none;\n}\n\n.fr-square {\n  flex: none;\n  justify-content: center;\n  width: 2.25rem;\n  padding-inline: 0;\n}\n\n.fr-toggle-chip {\n  border-color: var(--pm-border);\n  background: none;\n  color: var(--pm-muted);\n  cursor: pointer;\n}\n\n.fr-toggle-chip[aria-pressed='true'] {\n  border-color: var(--pm-accent-line);\n  background: var(--pm-accent-softer);\n  color: var(--pm-fg);\n}\n\n/* The tree scrolls on its own, so the filter and Notebook Goes In stay in view. */\n.fr-ftree {\n  flex: 1 1 12rem;\n  min-height: 10rem;\n  max-height: 22rem;\n  overflow-y: auto;\n  border: 1px solid var(--pm-border);\n  font-size: var(--pm-text-item);\n}\n\n.fr-frow-line {\n  display: flex;\n  align-items: stretch;\n  min-height: 2.25rem;\n}\n\n.fr-frow-line[data-dim] .fr-frow-text {\n  color: var(--pm-muted);\n}\n\n.fr-guide {\n  position: relative;\n  flex: none;\n  width: 1.1rem;\n}\n\n.fr-guide::before {\n  position: absolute;\n  inset: 0 auto 0 50%;\n  width: 1px;\n  background: var(--pm-border);\n  content: '';\n}\n\n.fr-guide[data-lit]::before {\n  background: var(--pm-accent-line);\n}\n\n.fr-twisty {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  width: 1.6rem;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: var(--pm-muted);\n}\n\nbutton.fr-twisty {\n  cursor: pointer;\n}\n\nbutton.fr-twisty:hover {\n  color: var(--pm-fg);\n}\n\n.fr-frow {\n  display: flex;\n  position: relative;\n  flex: 1 1 auto;\n  align-items: center;\n  gap: 0.55rem;\n  min-width: 0;\n  padding: 0.25rem 0.6rem 0.25rem 0.2rem;\n  cursor: pointer;\n}\n\n.fr-frow-root {\n  padding-left: 0.6rem;\n}\n\n.fr-frow > input {\n  position: absolute;\n  opacity: 0;\n  pointer-events: none;\n}\n\n.fr-frow:has(input:focus-visible) {\n  outline: 2px solid var(--pm-accent);\n  outline-offset: -2px;\n}\n\n.fr-frow:has(input:checked) {\n  background: var(--pm-accent-softer);\n}\n\n.fr-frow:has(input:checked) strong,\n.fr-frow:has(input:checked) .fr-frow-text > :first-child {\n  font-weight: var(--pm-weight-medium);\n}\n\n.fr-frow > .i {\n  flex: none;\n  color: var(--pm-muted);\n}\n\n.fr-frow-line[data-on-line] .fr-frow > .i,\n.fr-frow-root:has(input:checked) > .i,\n.fr-frow-held > .i {\n  color: var(--pm-accent);\n}\n\n.fr-frow-held {\n  cursor: default;\n}\n\n.fr-frow-held .btn {\n  flex: none;\n}\n\n.fr-frow-text {\n  display: grid;\n}\n\n.fr-ellipsis {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.fr-frow-notebook {\n  overflow: hidden;\n  color: var(--pm-accent);\n  font-size: var(--pm-text-meta);\n  font-weight: var(--pm-weight-meta);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.fr-frow-text > .muted {\n  font-size: var(--pm-text-meta);\n}\n\n.fr-frow-count {\n  flex: none;\n  padding: 0 0.4rem;\n  background: color-mix(in oklab, var(--pm-fg) 8%, transparent);\n  color: var(--pm-muted);\n  font-size: var(--pm-text-meta);\n  font-weight: var(--pm-weight-meta);\n}\n\n.fr-ftree mark {\n  background: none;\n  color: var(--pm-accent);\n  font-weight: var(--pm-weight-semibold);\n}\n\n.fr-ftree-none {\n  display: grid;\n  gap: 0.4rem;\n  padding: 1.25rem 0.75rem;\n}\n\n.fr-ftree-note {\n  padding: 0.5rem 0.75rem;\n}\n";
